// Class 7 Maths Preloaded Chapter Data for offline/file:// protocol fallback
window.CHAPTER_DATA = {"1":"<section class=\"chapter-section\" id=\"ch1\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">1</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 1: Integers</h2>\n      <p>NCERT Exercise 1.1 to 1.3 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Properties Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Integers (ℤ (Integers)):</strong> The set {..., -3, -2, -1, 0, 1, 2, 3, ...} containing whole numbers and their negatives.</li>\n      <li><strong>Addition &amp; Subtraction Properties:</strong>\n        <ul>\n          <li><em>Closure:</em> a + b and a - b are always integers.</li>\n          <li><em>Commutative:</em> a + b = b + a. (Note: a - b ≠ b - a).</li>\n          <li><em>Associative:</em> (a + b) + c = a + (b + c).</li>\n          <li><em>Additive Identity:</em> a + 0 = a = 0 + a. Additive inverse of a is -a.</li>\n        </ul>\n      </li>\n      <li><strong>Multiplication Properties:</strong>\n        <ul>\n          <li><em>Rules of Signs:</em> (+) × (+) = (+), (-) × (-) = (+), (+) × (-) = (-), (-) × (+) = (-).</li>\n          <li><em>Distributive Property over Addition:</em> a × (b + c) = (a × b) + (a × c).</li>\n          <li><em>Distributive Property over Subtraction:</em> a × (b - c) = (a × b) - (a × c).</li>\n          <li><em>Multiplicative Identity:</em> a × 1 = a. Product with zero: a × 0 = 0.</li>\n        </ul>\n      </li>\n      <li><strong>Division of Integers:</strong>\n        <ul>\n          <li>(-a) ÷ b = a ÷ (-b) = -(a ÷ b) when b ≠ 0.</li>\n          <li>(-a) ÷ (-b) = a ÷ b.</li>\n          <li>Division by 0 is meaningless (a ÷ 0 is undefined); 0 ÷ a = 0 (a ≠ 0); a ÷ 1 = a.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 1.1 -->\n  <div class=\"ex-div\">Exercise 1.1</div>\n\n  <div class=\"q-card\" id=\"q1_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Write down a pair of integers whose: (a) sum is −7, (b) difference is −10, (c) sum is 0.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Sum is −7:</strong><br>\n            Let the two integers be <span class=\"math\">−4</span> and <span class=\"math\">−3</span>.<br>\n            Verification: <span class=\"math\">(−4) + (−3) = −4 − 3 = −7</span>.<br>\n            <em>(Another valid pair: −10 and 3, since −10 + 3 = −7).</em>\n          </div>\n          <div class=\"step\">\n            <strong>(b) Difference is −10:</strong><br>\n            Let the two integers be <span class=\"math\">−12</span> and <span class=\"math\">−2</span>.<br>\n            Verification: <span class=\"math\">(−12) − (−2) = −12 + 2 = −10</span>.<br>\n            <em>(Another valid pair: 2 and 12, since 2 − 12 = −10).</em>\n          </div>\n          <div class=\"step\">\n            <strong>(c) Sum is 0:</strong><br>\n            Any integer and its additive inverse.<br>\n            Let the integers be <span class=\"math\">5</span> and <span class=\"math\">−5</span>.<br>\n            Verification: <span class=\"math\">5 + (−5) = 5 − 5 = 0</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): Stating a valid pair with verification</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): Stating a valid pair with subtraction step</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c): Stating additive inverse pair with sum verification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">(a) Write a pair of negative integers whose difference gives 8.<br>(b) Write a negative integer and a positive integer whose sum is −5.<br>(c) Write a negative integer and a positive integer whose difference is −3.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Pair of negative integers with difference 8:</strong><br>\n            Let the negative integers be <span class=\"math\">−2</span> and <span class=\"math\">−10</span>.<br>\n            Calculation: <span class=\"math\">(−2) − (−10) = −2 + 10 = 8</span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) Negative integer and positive integer with sum −5:</strong><br>\n            Let the negative integer be <span class=\"math\">−7</span> and the positive integer be <span class=\"math\">2</span>.<br>\n            Calculation: <span class=\"math\">(−7) + 2 = −5</span>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) Negative integer and positive integer with difference −3:</strong><br>\n            Let the negative integer be <span class=\"math\">−1</span> and the positive integer be <span class=\"math\">2</span>.<br>\n            Calculation: <span class=\"math\">(−1) − (+2) = −1 − 2 = −3</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): (−2) − (−10) = 8 with signs shown</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): (−7) + 2 = −5</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c): (−1) − 2 = −3</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">In a quiz, team A scored −40, 10, 0 and team B scored 10, 0, −40 in three successive rounds. Which team scored more? Can we say that we can add integers in any order?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Total score of Team A:</strong><br>\n            <span class=\"math\">Total score of Team A = (−40) + 10 + 0 = −30</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Total score of Team B:</strong><br>\n            <span class=\"math\">Total score of Team B = 10 + 0 + (−40) = 10 − 40 = −30</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Comparison &amp; Order Property:</strong><br>\n            Both teams scored <span class=\"math\">−30</span>. Hence, both teams scored equally; neither team scored more.<br>\n            <strong>Yes</strong>, we can add integers in any order due to the <strong>Commutative and Associative Properties of addition</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating both total scores accurately (−30 each)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative answer stating commutative property</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Fill in the blanks to make the following statements true:<br>(i) (−5) + (−8) = (−8) + (.....)<br>(ii) −53 + ..... = −53<br>(iii) 17 + ..... = 0<br>(iv) [13 + (−12)] + (.....) = 13 + [(−12) + (−7)]<br>(v) (−4) + [15 + (−3)] = [(−4) + 15] + (.....)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) (−5) + (−8) = (−8) + (−5)</strong> &nbsp;&nbsp;<em>[Commutative property: a + b = b + a]</em><br>\n            <strong>(ii) −53 + 0 = −53</strong> &nbsp;&nbsp;<em>[Additive identity: a + 0 = a]</em><br>\n            <strong>(iii) 17 + (−17) = 0</strong> &nbsp;&nbsp;<em>[Additive inverse: a + (-a) = 0]</em><br>\n            <strong>(iv) [13 + (−12)] + (−7) = 13 + [(−12) + (−7)]</strong> &nbsp;&nbsp;<em>[Associative property]</em><br>\n            <strong>(v) (−4) + [15 + (−3)] = [(−4) + 15] + (−3)</strong> &nbsp;&nbsp;<em>[Associative property]</em>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct fill-in-the-blank with underlying property</span><span class=\"marking-marks\">0.6 Mark each (Total 3 Marks)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 1.2 -->\n  <div class=\"ex-div\">Exercise 1.2</div>\n\n  <div class=\"q-card\" id=\"q1_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find each of the following products:<br>(a) 3 × (−1)<br>(b) (−1) × 225<br>(c) (−21) × (−30)<br>(d) (−316) × (−1)<br>(e) (−15) × 0 × (−18)<br>(f) (−12) × (−11) × (10)<br>(g) 9 × (−3) × (−6)<br>(h) (−18) × (−5) × (−4)<br>(i) (−1) × (−2) × (−3) × 4<br>(j) (−3) × (−6) × (−2) × (−1)</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">3 × (−1) = −3</span></strong> &nbsp;<em>[(+) × (−) = (−)]</em><br>\n            <strong>(b) <span class=\"math\">(−1) × 225 = −225</span></strong><br>\n            <strong>(c) <span class=\"math\">(−21) × (−30) = +(21 × 30) = <strong>630</strong></span></strong> &nbsp;<em>[(−) × (−) = (+)]</em><br>\n            <strong>(d) <span class=\"math\">(−316) × (−1) = <strong>316</strong></span></strong><br>\n            <strong>(e) <span class=\"math\">(−15) × 0 × (−18) = <strong>0</strong></span></strong> &nbsp;<em>[Any number multiplied by 0 is 0]</em><br>\n            <strong>(f) <span class=\"math\">(−12) × (−11) × 10 = 132 × 10 = <strong>1320</strong></span></strong><br>\n            <strong>(g) <span class=\"math\">9 × (−3) × (−6) = 9 × 18 = <strong>162</strong></span></strong><br>\n            <strong>(h) <span class=\"math\">(−18) × (−5) × (−4) = 90 × (−4) = <strong>−360</strong></span></strong> &nbsp;<em>[3 negative signs ⇒ result is negative]</em><br>\n            <strong>(i) <span class=\"math\">(−1) × (−2) × (−3) × 4 = [2] × [−12] = <strong>−24</strong></span></strong><br>\n            <strong>(j) <span class=\"math\">(−3) × (−6) × (−2) × (−1) = 18 × 2 = <strong>36</strong></span></strong> &nbsp;<em>[4 negative signs ⇒ result is positive]</em>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sign rule correct application</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">All 10 numerical values accurately computed</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Verify the following:<br>(a) 18 × [7 + (−3)] = [18 × 7] + [18 × (−3)]<br>(b) (−21) × [(−4) + (−6)] = [(−21) × (−4)] + [(−21) × (−6)]</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Verification of Distributive Property:</strong><br>\n            <span class=\"math\">LHS = 18 × [7 + (−3)] = 18 × [7 − 3] = 18 × 4 = <strong>72</strong></span>.<br>\n            <span class=\"math\">RHS = [18 × 7] + [18 × (−3)] = 126 + (−54) = 126 − 54 = <strong>72</strong></span>.<br>\n            Since <span class=\"math\">LHS = RHS = 72</span>, the statement is <strong>verified</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) Verification:</strong><br>\n            <span class=\"math\">LHS = (−21) × [(−4) + (−6)] = (−21) × [−10] = <strong>210</strong></span>.<br>\n            <span class=\"math\">RHS = [(−21) × (−4)] + [(−21) × (−6)] = 84 + 126 = <strong>210</strong></span>.<br>\n            Since <span class=\"math\">LHS = RHS = 210</span>, the statement is <strong>verified</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): LHS = 72 and RHS = 72 shown with conclusion</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): LHS = 210 and RHS = 210 shown with conclusion</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Find the product using suitable properties:<br>(a) 26 × (−48) + (−48) × (−36)<br>(b) 8 × 53 × (−125)<br>(c) 15 × (−25) × (−4) × (−10)<br>(d) (−41) × 102<br>(e) 625 × (−35) + (−625) × 65<br>(f) 7 × (50 − 2)<br>(g) (−17) × (−29)<br>(h) (−57) × (−19) + 57</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">26 × (−48) + (−48) × (−36)</span>:</strong><br>\n            Take common factor <span class=\"math\">(−48)</span> using Distributive Property:<br>\n            <span class=\"math\">= (−48) × [26 + (−36)] = (−48) × (−10) = <strong>480</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) <span class=\"math\">8 × 53 × (−125)</span>:</strong><br>\n            Regroup using Associative &amp; Commutative Property:<br>\n            <span class=\"math\">= [8 × (−125)] × 53 = (−1000) × 53 = <strong>−53000</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) <span class=\"math\">15 × (−25) × (−4) × (−10)</span>:</strong><br>\n            Group <span class=\"math\">(−25) × (−4) = 100</span>:<br>\n            <span class=\"math\">= 15 × 100 × (−10) = 1500 × (−10) = <strong>−15000</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(d) <span class=\"math\">(−41) × 102</span>:</strong><br>\n            Write <span class=\"math\">102 = 100 + 2</span>:<br>\n            <span class=\"math\">= (−41) × (100 + 2) = (−41 × 100) + (−41 × 2) = −4100 − 82 = <strong>−4182</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(e) <span class=\"math\">625 × (−35) + (−625) × 65</span>:</strong><br>\n            Rewrite <span class=\"math\">(−625) × 65 = 625 × (−65)</span>:<br>\n            <span class=\"math\">= 625 × [(−35) + (−65)] = 625 × (−100) = <strong>−62500</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(f) <span class=\"math\">7 × (50 − 2)</span>:</strong><br>\n            <span class=\"math\">= (7 × 50) − (7 × 2) = 350 − 14 = <strong>336</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(g) <span class=\"math\">(−17) × (−29)</span>:</strong><br>\n            Write <span class=\"math\">−29 = −30 + 1</span>:<br>\n            <span class=\"math\">= (−17) × (−30 + 1) = [(−17) × (−30)] + [(−17) × 1] = 510 − 17 = <strong>493</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(h) <span class=\"math\">(−57) × (−19) + 57</span>:</strong><br>\n            Note that <span class=\"math\">(−57) × (−19) = 57 × 19</span> and <span class=\"math\">57 = 57 × 1</span>:<br>\n            <span class=\"math\">= 57 × [19 + 1] = 57 × 20 = <strong>1140</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating property name (Distributive / Regrouping)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate step-by-step simplification for all parts</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 1.3 -->\n  <div class=\"ex-div\">Exercise 1.3</div>\n\n  <div class=\"q-card\" id=\"q1_3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Evaluate each of the following:<br>(a) (−30) ÷ 10<br>(b) 50 ÷ (−5)<br>(c) (−36) ÷ (−9)<br>(d) (−49) ÷ (49)<br>(e) 13 ÷ [(−2) + 1]<br>(f) 0 ÷ (−12)<br>(g) (−31) ÷ [(−30) + (−1)]<br>(h) [(−36) ÷ 12] ÷ 3<br>(i) [(−6) + 5] ÷ [(−2) + 1]</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">(−30) ÷ 10 = −30/10 = <strong>−3</strong></span></strong><br>\n            <strong>(b) <span class=\"math\">50 ÷ (−5) = −50/5 = <strong>−10</strong></span></strong><br>\n            <strong>(c) <span class=\"math\">(−36) ÷ (−9) = +36/9 = <strong>4</strong></span></strong><br>\n            <strong>(d) <span class=\"math\">(−49) ÷ 49 = <strong>−1</strong></span></strong><br>\n            <strong>(e) <span class=\"math\">13 ÷ [(−2) + 1] = 13 ÷ (−1) = <strong>−13</strong></span></strong><br>\n            <strong>(f) <span class=\"math\">0 ÷ (−12) = <strong>0</strong></span></strong> &nbsp;<em>[Zero divided by any non-zero integer is 0]</em><br>\n            <strong>(g) <span class=\"math\">(−31) ÷ [(−30) + (−1)] = (−31) ÷ (−31) = <strong>1</strong></span></strong><br>\n            <strong>(h) <span class=\"math\">[(−36) ÷ 12] ÷ 3 = (−3) ÷ 3 = <strong>−1</strong></span></strong><br>\n            <strong>(i) <span class=\"math\">[(−6) + 5] ÷ [(−2) + 1] = (−1) ÷ (−1) = <strong>1</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sign rule in division accurately applied</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct evaluation of nested brackets</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Verify that a ÷ (b + c) ≠ (a ÷ b) + (a ÷ c) for each of the following values of a, b and c:<br>(a) a = 12, b = −4, c = 2<br>(b) a = (−10), b = 1, c = 1</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) When a = 12, b = −4, c = 2:</strong><br>\n            <span class=\"math\">LHS = a ÷ (b + c) = 12 ÷ [(−4) + 2] = 12 ÷ (−2) = <strong>−6</strong></span>.<br>\n            <span class=\"math\">RHS = (a ÷ b) + (a ÷ c) = [12 ÷ (−4)] + [12 ÷ 2] = (−3) + 6 = <strong>3</strong></span>.<br>\n            Since <span class=\"math\">−6 ≠ 3</span>, <span class=\"math\">LHS ≠ RHS</span>. Verified that division is not distributive over addition!\n          </div>\n          <div class=\"step\">\n            <strong>(b) When a = −10, b = 1, c = 1:</strong><br>\n            <span class=\"math\">LHS = (−10) ÷ (1 + 1) = (−10) ÷ 2 = <strong>−5</strong></span>.<br>\n            <span class=\"math\">RHS = [(−10) ÷ 1] + [(−10) ÷ 1] = (−10) + (−10) = <strong>−20</strong></span>.<br>\n            Since <span class=\"math\">−5 ≠ −20</span>, <span class=\"math\">LHS ≠ RHS</span>. Verified!\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): LHS = −6, RHS = 3, LHS ≠ RHS</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): LHS = −5, RHS = −20, LHS ≠ RHS</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_3_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">An elevator descends into a mine shaft at the rate of 6 m/min. If the descent starts from 10 m above the ground level, how long will it take to reach −350 m?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Determine total distance to descend:</strong><br>\n            Initial position = <span class=\"math\">+10 m</span> (above ground).<br>\n            Final position = <span class=\"math\">−350 m</span> (below ground).<br>\n            Total distance = <span class=\"math\">10 − (−350) = 10 + 350 = <strong>360 m</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Calculate time taken:</strong><br>\n            Speed of descent = <span class=\"math\">6 m/min</span>.<br>\n            <span class=\"math\">Time taken = Distance/Speed = 360/6 = <strong>60 minutes</strong> = <strong>1 hour</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The elevator will take <strong>1 hour (60 minutes)</strong> to reach −350 m.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Distance formulation: 10 − (−350) = 360 m</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Time = 360/6 = 60 min = 1 hour with unit</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Temperature Variation</div>\n        <div class=\"cbq-question\"><strong>Scenario:</strong> In a cold storage plant, the temperature at 12:00 noon was 10°C above zero. It decreases at a rate of 2°C per hour until midnight. (i) At what time would the temperature be 8°C below zero? (ii) What would be the temperature at midnight?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Time when temperature is 8°C below zero (−8°C):</strong><br>\n          Initial temp = +10°C; Target temp = −8°C.<br>\n          Total drop in temp = <span class=\"math\">10 − (−8) = 18°C</span>.<br>\n          Rate of drop = <span class=\"math\">2°C/hour</span>.<br>\n          Time taken = <span class=\"math\">18 ÷ 2 = 9 hours</span>.<br>\n          Time = 12 noon + 9 hours = <strong>9:00 PM</strong>.</p>\n          <p><strong>(ii) Temperature at midnight (12:00 AM):</strong><br>\n          Time duration from 12 noon to 12 midnight = 12 hours.<br>\n          Drop in temperature = <span class=\"math\">12 × 2°C = 24°C</span>.<br>\n          Temp at midnight = <span class=\"math\">10 − 24 = <strong>−14°C</strong></span>.</p>\n        </div>\n      </div>\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#10b981;\">⚡ Assertion &amp; Reason</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> The product of an odd number of negative integers is always negative.<br>\n          <strong>Reason (R):</strong> Two negative signs pair up to produce a positive sign, leaving one unpaired negative sign when the count is odd.<br>\n          Choose: (a) Both A and R are true and R is correct explanation of A. (b) Both A and R are true, but R is not correct explanation. (c) A is true, R is false. (d) A is false, R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <strong>Answer: (a) Both A and R are true and R is the correct explanation of A.</strong><br>\n          <em>Explanation:</em> Every pair of negative integers gives a positive product: <span class=\"math\">(−) × (−) = (+)</span>. For an odd count <span class=\"math\">2k + 1</span>, the <span class=\"math\">k</span> pairs give <span class=\"math\">(+)</span>, and multiplying with the remaining negative integer yields <span class=\"math\">(+) × (−) = (−)</span>.\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" disabled style=\"opacity:.35;\">← Previous</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\">Chapter 2: Fractions &amp; Decimals →</button>\n  </div>\n</section>\n","2":"<section class=\"chapter-section\" id=\"ch2\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">2</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 2: Fractions and Decimals</h2>\n      <p>NCERT Exercise 2.1 to 2.5 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Formulas Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Types of Fractions:</strong>\n        <ul>\n          <li><em>Proper Fraction:</em> Numerator &lt; Denominator (e.g. 3/5). Value &lt; 1.</li>\n          <li><em>Improper Fraction:</em> Numerator ≥ Denominator (e.g. 7/4). Value ≥ 1. Can be written as Mixed Fraction: 1 3/4.</li>\n        </ul>\n      </li>\n      <li><strong>Multiplication of Fractions:</strong>\n        (Numerator₁ × Numerator₂)/(Denominator₁ × Denominator₂)\n        The operator 'of' signifies multiplication: 1/2 of  24 = 1/2 × 24 = 12.\n      </li>\n      <li><strong>Reciprocal of a Fraction:</strong> The non-zero number obtained by interchanging numerator and denominator. Product with original fraction equals 1: a/b × b/a = 1.</li>\n      <li><strong>Division of Fractions:</strong> Multiply by the reciprocal of the divisor: a/b ÷ c/d = a/b × d/c.</li>\n      <li><strong>Decimal Operations:</strong>\n        <ul>\n          <li>Multiplying by 10, 100, 1000: Shift decimal point to the right by as many places as there are zeros.</li>\n          <li>Dividing by 10, 100, 1000: Shift decimal point to the left by as many places as there are zeros.</li>\n          <li>Division by decimal: Multiply both dividend and divisor by suitable powers of 10 to make divisor a whole number.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 2.1 -->\n  <div class=\"ex-div\">Exercise 2.1</div>\n\n  <div class=\"q-card\" id=\"q2_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Solve the following fractions:<br>(i) 2 − 3/5<br>(ii) 4 + 7/8<br>(iii) 3/5 + 2/7<br>(iv) 9/11 − 4/15<br>(v) 7/10 + 2/5 + 3/2<br>(vi) 2⅔ + 3½<br>(vii) 8½ − 3⅝</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">2 − 3/5</span>:</strong><br>\n            <span class=\"math\">= 2/1 − 3/5 = (2 × 5 − 3)/5 = (10 − 3)/5 = <strong>7/5</strong> = <strong>1 2/5</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">4 + 7/8</span>:</strong><br>\n            <span class=\"math\">= (4 × 8 + 7)/8 = (32 + 7)/8 = <strong>39/8</strong> = <strong>4 7/8</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">3/5 + 2/7</span>:</strong><br>\n            LCM of 5 and 7 is 35.<br>\n            <span class=\"math\">= (3 × 7 + 2 × 5)/35 = (21 + 10)/35 = <strong>31/35</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) <span class=\"math\">9/11 − 4/15</span>:</strong><br>\n            LCM of 11 and 15 is 165.<br>\n            <span class=\"math\">= (9 × 15 − 4 × 11)/165 = (135 − 44)/165 = <strong>91/165</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(v) <span class=\"math\">7/10 + 2/5 + 3/2</span>:</strong><br>\n            LCM of 10, 5, 2 is 10.<br>\n            <span class=\"math\">= (7 + (2 × 2) + (3 × 5))/10 = (7 + 4 + 15)/10 = 26/10 = <strong>13/5</strong> = <strong>2 3/5</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(vi) <span class=\"math\">2 2/3 + 3 1/2</span>:</strong><br>\n            Convert to improper fractions: <span class=\"math\">8/3 + 7/2</span>. LCM of 3, 2 is 6.<br>\n            <span class=\"math\">= (8 × 2 + 7 × 3)/6 = (16 + 21)/6 = <strong>37/6</strong> = <strong>6 1/6</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(vii) <span class=\"math\">8 1/2 − 3 5/8</span>:</strong><br>\n            Convert to improper fractions: <span class=\"math\">17/2 − 29/8</span>. LCM of 2, 8 is 8.<br>\n            <span class=\"math\">= (17 × 4 − 29)/8 = (68 − 29)/8 = <strong>39/8</strong> = <strong>4 7/8</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">LCM determination and equivalent fractions</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correctly evaluated and simplified final fractions</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Arrange the following in descending order:<br>(i) 2/9, 2/3, 8/21<br>(ii) 1/5, 3/7, 7/10</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 2/9, 2/3, 8/21:</strong><br>\n            LCM of denominators 9, 3, 21 is 63.<br>\n            Convert each to like fractions:<br>\n            <span class=\"math\">2/9 = (2 × 7)/63 = 14/63</span><br>\n            <span class=\"math\">2/3 = (2 × 21)/63 = 42/63</span><br>\n            <span class=\"math\">8/21 = (8 × 3)/63 = 24/63</span><br>\n            Comparing numerators: <span class=\"math\">42 > 24 > 14</span>.<br>\n            <strong>Descending order: <span class=\"math\"><strong>2/3 > 8/21 > 2/9</strong></span></strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) 1/5, 3/7, 7/10:</strong><br>\n            LCM of 5, 7, 10 is 70.<br>\n            <span class=\"math\">1/5 = (1 × 14)/70 = 14/70</span><br>\n            <span class=\"math\">3/7 = (3 × 10)/70 = 30/70</span><br>\n            <span class=\"math\">7/10 = (7 × 7)/70 = 49/70</span><br>\n            Comparing numerators: <span class=\"math\">49 > 30 > 14</span>.<br>\n            <strong>Descending order: <span class=\"math\"><strong>7/10 > 3/7 > 1/5</strong></span></strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): LCM = 63 and correct descending order</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): LCM = 70 and correct descending order</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 2.2 -->\n  <div class=\"ex-div\">Exercise 2.2</div>\n\n  <div class=\"q-card\" id=\"q2_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Multiply and reduce to lowest form and convert into a mixed fraction:<br>(i) 7 × 3/5<br>(ii) 4 × 1/3<br>(iii) 2 × 6/7<br>(iv) 5 × 2/9<br>(v) 2/3 × 4<br>(vi) 5/2 × 6<br>(vii) 11 × 4/7</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">7 × 3/5 = 21/5 = <strong>4 1/5</strong></span></strong><br>\n            <strong>(ii) <span class=\"math\">4 × 1/3 = 4/3 = <strong>1 1/3</strong></span></strong><br>\n            <strong>(iii) <span class=\"math\">2 × 6/7 = 12/7 = <strong>1 5/7</strong></span></strong><br>\n            <strong>(iv) <span class=\"math\">5 × 2/9 = 10/9 = <strong>1 1/9</strong></span></strong><br>\n            <strong>(v) <span class=\"math\">2/3 × 4 = 8/3 = <strong>2 2/3</strong></span></strong><br>\n            <strong>(vi) <span class=\"math\">5/2 × 6 = 5 × 3 = <strong>15</strong></span></strong><br>\n            <strong>(vii) <span class=\"math\">11 × 4/7 = 44/7 = <strong>6 2/7</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Numerator multiplication and conversion to mixed fraction</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find: (a) ½ of (i) 24 (ii) 46<br>(b) ⅔ of (i) 18 (ii) 27<br>(c) ¾ of (i) 16 (ii) 36</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) ½ of:</strong><br>\n            (i) <span class=\"math\">1/2 × 24 = <strong>12</strong></span><br>\n            (ii) <span class=\"math\">1/2 × 46 = <strong>23</strong></span>\n          </div>\n          <div class=\"step\">\n            <strong>(b) ⅔ of:</strong><br>\n            (i) <span class=\"math\">2/3 × 18 = 2 × 6 = <strong>12</strong></span><br>\n            (ii) <span class=\"math\">2/3 × 27 = 2 × 9 = <strong>18</strong></span>\n          </div>\n          <div class=\"step\">\n            <strong>(c) ¾ of:</strong><br>\n            (i) <span class=\"math\">3/4 × 16 = 3 × 4 = <strong>12</strong></span><br>\n            (ii) <span class=\"math\">3/4 × 36 = 3 × 9 = <strong>27</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with multiplication setup</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">A car runs 16 km using 1 litre of petrol. How much distance will it cover using 2¾ litres of petrol?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Quantity of petrol given:</strong><br>\n            <span class=\"math\">2 3/4 litres = (2 × 4 + 3)/4 = 11/4 litres</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Calculate total distance:</strong><br>\n            Distance covered in 1 litre = <span class=\"math\">16 km</span>.<br>\n            Total distance = <span class=\"math\">16 × 11/4 = (16 × 11)/4 = 4 × 11 = <strong>44 km</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The car will cover <strong>44 km</strong> using 2¾ litres of petrol.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Improper fraction conversion: 11/4 litres</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplication 16 × (11/4) = 44 km with statement</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 2.3 -->\n  <div class=\"ex-div\">Exercise 2.3</div>\n\n  <div class=\"q-card\" id=\"q2_3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the reciprocal of each of the following fractions. Classify the reciprocals as proper fractions, improper fractions and whole numbers:<br>(i) 3/7 (ii) 5/8 (iii) 9/7 (iv) 6/5 (v) 12/7 (vi) 1/8 (vii) 1/11</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            (i) Reciprocal of <span class=\"math\">3/7</span> is <span class=\"math\"><strong>7/3</strong></span> ⇒ <strong>Improper fraction</strong>.<br>\n            (ii) Reciprocal of <span class=\"math\">5/8</span> is <span class=\"math\"><strong>8/5</strong></span> ⇒ <strong>Improper fraction</strong>.<br>\n            (iii) Reciprocal of <span class=\"math\">9/7</span> is <span class=\"math\"><strong>7/9</strong></span> ⇒ <strong>Proper fraction</strong>.<br>\n            (iv) Reciprocal of <span class=\"math\">6/5</span> is <span class=\"math\"><strong>5/6</strong></span> ⇒ <strong>Proper fraction</strong>.<br>\n            (v) Reciprocal of <span class=\"math\">12/7</span> is <span class=\"math\"><strong>7/12</strong></span> ⇒ <strong>Proper fraction</strong>.<br>\n            (vi) Reciprocal of <span class=\"math\">1/8</span> is <span class=\"math\">8/1 = <strong>8</strong></span> ⇒ <strong>Whole number</strong>.<br>\n            (vii) Reciprocal of <span class=\"math\">1/11</span> is <span class=\"math\">11/1 = <strong>11</strong></span> ⇒ <strong>Whole number</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reciprocal values correctly found</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate classification (Proper / Improper / Whole)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find: (i) 7/3 ÷ 2, (ii) 4/9 ÷ 5, (iii) 4⅓ ÷ 3, (iv) 2/5 ÷ 1/2, (v) 3½ ÷ 8/7, (vi) 2⅕ ÷ 1⅕.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">7/3 ÷ 2 = 7/3 × 1/2 = <strong>7/6</strong> = <strong>1 1/6</strong></span></strong><br>\n            <strong>(ii) <span class=\"math\">4/9 ÷ 5 = 4/9 × 1/5 = <strong>4/45</strong></span></strong><br>\n            <strong>(iii) <span class=\"math\">4 1/3 ÷ 3 = 13/3 × 1/3 = <strong>13/9</strong> = <strong>1 4/9</strong></span></strong><br>\n            <strong>(iv) <span class=\"math\">2/5 ÷ 1/2 = 2/5 × 2/1 = <strong>4/5</strong></span></strong><br>\n            <strong>(v) <span class=\"math\">3 1/2 ÷ 8/7 = 7/2 × 7/8 = <strong>49/16</strong> = <strong>3 1/16</strong></span></strong><br>\n            <strong>(vi) <span class=\"math\">2 1/5 ÷ 1 1/5 = 11/5 ÷ 6/5 = 11/5 × 5/6 = <strong>11/6</strong> = <strong>1 5/6</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reciprocal multiplication rule application</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate simplified fraction values</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 2.4 & 2.5 -->\n  <div class=\"ex-div\">Exercise 2.4 &amp; 2.5 (Decimals Operations)</div>\n\n  <div class=\"q-card\" id=\"q2_4_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_4_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the product:<br>(i) 0.2 × 6<br>(ii) 8 × 4.6<br>(iii) 2.71 × 5<br>(iv) 20.1 × 4<br>(v) 0.05 × 7<br>(vi) 211.02 × 4<br>(vii) 2 × 0.86</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">0.2 × 6 = <strong>1.2</strong></span></strong><br>\n            <strong>(ii) <span class=\"math\">8 × 4.6 = <strong>36.8</strong></span></strong><br>\n            <strong>(iii) <span class=\"math\">2.71 × 5 = <strong>13.55</strong></span></strong><br>\n            <strong>(iv) <span class=\"math\">20.1 × 4 = <strong>80.4</strong></span></strong><br>\n            <strong>(v) <span class=\"math\">0.05 × 7 = <strong>0.35</strong></span></strong><br>\n            <strong>(vi) <span class=\"math\">211.02 × 4 = <strong>844.08</strong></span></strong><br>\n            <strong>(vii) <span class=\"math\">2 × 0.86 = <strong>1.72</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Count of decimal places correctly maintained</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate multiplication arithmetic</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_5_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_5_1')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find:<br>(a) 7.75 ÷ 0.25<br>(b) 76.5 ÷ 0.15<br>(c) 37.8 ÷ 1.4<br>(d) 2.7 ÷ 100<br>(e) 0.5 ÷ 1000<br>(f) 7 ÷ 3.5</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">7.75 ÷ 0.25 = 775/25 = <strong>31</strong></span></strong><br>\n            <strong>(b) <span class=\"math\">76.5 ÷ 0.15 = 7650/15 = <strong>510</strong></span></strong><br>\n            <strong>(c) <span class=\"math\">37.8 ÷ 1.4 = 378/14 = <strong>27</strong></span></strong><br>\n            <strong>(d) <span class=\"math\">2.7 ÷ 100 = <strong>0.027</strong></span></strong> &nbsp;<em>[Shift decimal 2 places left]</em><br>\n            <strong>(e) <span class=\"math\">0.5 ÷ 1000 = <strong>0.0005</strong></span></strong> &nbsp;<em>[Shift decimal 3 places left]</em><br>\n            <strong>(f) <span class=\"math\">7 ÷ 3.5 = 70/35 = <strong>2</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with step</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Uniform Tailoring</div>\n        <div class=\"cbq-question\"><strong>Scenario:</strong> A school needs 1.8 metres of cloth to stitch one uniform shirt. A roll of fabric contains 45 metres of cloth. (i) How many complete shirts can be tailored from this roll? (ii) What length of fabric will be left? (iii) If each shirt requires 6 buttons, how many buttons will be needed in total?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Number of shirts:</strong><br>\n          <span class=\"math\">Number of shirts = (Total cloth)/(Cloth per shirt) = 45 ÷ 1.8 = 450/18 = <strong>25 complete shirts</strong></span>.</p>\n          <p><strong>(ii) Leftover fabric:</strong><br>\n          Total used = <span class=\"math\">25 × 1.8 = 45 m</span>. Leftover = <span class=\"math\">45 − 45 = <strong>0 metres</strong></span>.</p>\n          <p><strong>(iii) Total buttons needed:</strong><br>\n          <span class=\"math\">25 × 6 = <strong>150 buttons</strong></span>.</p>\n        </div>\n      </div>\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#10b981;\">⚡ HOTS Question</div>\n        <div class=\"cbq-question\">Each side of a regular polygon is 2.5 cm in length. The perimeter of the polygon is 12.5 cm. How many sides does the polygon have?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p>Let number of sides be <span class=\"math\">n</span>.<br>\n          In a regular polygon, all sides are equal. Perimeter = <span class=\"math\">n × side</span>.<br>\n          <span class=\"math\">n × 2.5 = 12.5 ⇒ n = 12.5/2.5 = 125/25 = <strong>5</strong></span>.<br>\n          Therefore, the polygon has <strong>5 sides</strong> (it is a regular pentagon).</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(1)\">← Chapter 1: Integers</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\">Chapter 3: Data Handling →</button>\n  </div>\n</section>\n","3":"<section class=\"chapter-section\" id=\"ch3\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">3</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 3: Data Handling</h2>\n      <p>NCERT Exercise 3.1 to 3.4 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Formulas Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Data &amp; Range:</strong>\n        Range = Highest Value - Lowest Value\n      </li>\n      <li><strong>Arithmetic Mean (Average):</strong>\n        Mean = (Sum of all observations)/(Number of observations)\n      </li>\n      <li><strong>Mode:</strong> The observation that occurs most frequently in the given data. A data set can have more than one mode (multimodal).</li>\n      <li><strong>Median:</strong> The middle observation when data is arranged in ascending or descending order.\n        <ul>\n          <li>For odd n: Median = ((n+1)/2)th observation.</li>\n        </ul>\n      </li>\n      <li><strong>Bar Graphs:</strong> Representation of numbers using bars of uniform width where lengths/heights are proportional to the frequencies. Double bar graphs compare two sets of data simultaneously.</li>\n      <li><strong>Probability (P):</strong> Measure of chance of an event happening:\n        P(Event) = (Number of favourable outcomes)/(Total number of possible outcomes)\n        0 ≤ P ≤ 1. Impossible event = 0, Certain event = 1.\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 3.1 -->\n  <div class=\"ex-div\">Exercise 3.1</div>\n\n  <div class=\"q-card\" id=\"q3_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the range of heights of any ten students of your class.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Sample Data (Heights in cm):</strong><br>\n            Let the heights of 10 students be: <span class=\"math\">128, 132, 135, 139, 140, 142, 145, 148, 150, 152 cm</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Calculation of Range:</strong><br>\n            Highest height = <span class=\"math\">152 cm</span><br>\n            Lowest height = <span class=\"math\">128 cm</span><br>\n            <span class=\"math\">Range = Highest height − Lowest height = 152 − 128 = <strong>24 cm</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing observations &amp; identifying max/min values</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying Range formula and correct result</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the mean of the first five whole numbers.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Identify whole numbers:</strong><br>\n            The first five whole numbers are: <span class=\"math\">0, 1, 2, 3, 4</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Calculate sum and mean:</strong><br>\n            Sum = <span class=\"math\">0 + 1 + 2 + 3 + 4 = 10</span>.<br>\n            Number of observations = <span class=\"math\">5</span>.<br>\n            <span class=\"math\">Mean = (Sum of observations)/(Number of observations) = 10/5 = <strong>2</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The mean of the first five whole numbers is <strong>2</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing correct numbers starting from 0</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mean formula &amp; final answer 2</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">A cricketer scores the following runs in eight innings: 58, 76, 40, 35, 46, 45, 0, 100. Find the mean score.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Sum of runs:</strong><br>\n            <span class=\"math\">Total runs = 58 + 76 + 40 + 35 + 46 + 45 + 0 + 100 = <strong>400</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Number of innings:</strong><br>\n            <span class=\"math\">n = 8</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Mean score:</strong><br>\n            <span class=\"math\">Mean = (Total runs)/(Number of innings) = 400/8 = <strong>50</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The mean score of the cricketer is <strong>50 runs</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sum of observations = 400</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mean = 400/8 = 50 runs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 3.2 -->\n  <div class=\"ex-div\">Exercise 3.2</div>\n\n  <div class=\"q-card\" id=\"q3_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">The scores in mathematics test (out of 25) of 15 students is as follows: 19, 25, 23, 20, 9, 20, 15, 10, 5, 16, 25, 20, 24, 12, 20. Find the mode and median of this data. Are they same?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Arrange data in ascending order:</strong><br>\n            <span class=\"math\">5, 9, 10, 12, 15, 16, 19, <strong>20</strong>, 20, 20, 20, 23, 24, 25, 25</span>.<br>\n            Total students, <span class=\"math\">n = 15</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Find Mode:</strong><br>\n            The score 20 occurs 4 times (highest frequency).<br>\n            Therefore, <strong>Mode = 20</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Find Median:</strong><br>\n            Since <span class=\"math\">n = 15</span> is odd:<br>\n            <span class=\"math\">Median = ((15+1)/2)th observation = 8th observation = <strong>20</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Conclusion:</strong><br>\n            <strong>Yes</strong>, the mode and median are the same (both equal 20).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ascending order + Mode = 20</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Median = 8th value = 20</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative conclusion stating both are equal</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">The weights (in kg) of 15 students of a class are: 38, 42, 35, 37, 45, 50, 32, 43, 43, 40, 36, 38, 43, 38, 47.<br>(i) Find the mode and median of this data.<br>(ii) Is there more than one mode?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Arranging in ascending order:</strong><br>\n            <span class=\"math\">32, 35, 36, 37, 38, 38, 38, <strong>40</strong>, 42, 43, 43, 43, 45, 47, 50</span>.<br>\n            Total number of observations, <span class=\"math\">n = 15</span>.\n          </div>\n          <div class=\"step\">\n            <strong>(i) Mode and Median:</strong><br>\n            • Both <strong>38</strong> and <strong>43</strong> occur 3 times each (highest frequency).<br>\n            Therefore, <strong>Modes = 38 kg and 43 kg</strong> (bimodal).<br>\n            • <span class=\"math\">Median = ((15+1)/2)th observation = 8th observation = <strong>40 kg</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Is there more than one mode?</strong><br>\n            <strong>Yes</strong>, there are two modes (38 kg and 43 kg).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Modes: 38 and 43 kg</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Median: 40 kg</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Yes, with two modes mentioned</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 3.3 & 3.4 -->\n  <div class=\"ex-div\">Exercise 3.3 &amp; 3.4 (Graphs &amp; Probability)</div>\n\n  <div class=\"q-card\" id=\"q3_3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Consider this data collected from a survey of a colony:<br>Cricket (Watch: 1240, Participate: 620), Basketball (Watch: 470, Participate: 320), Swimming (Watch: 510, Participate: 320), Hockey (Watch: 430, Participate: 250), Athletics (Watch: 250, Participate: 105).<br>(i) Which sport is most popular?<br>(ii) Which is more preferred, watching or participating in sports?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Most popular sport:</strong><br>\n            Total people interested in Cricket = <span class=\"math\">1240 + 620 = 1860</span>.<br>\n            Cricket has the highest bar for both watching and participating.<br>\n            <strong>Answer: Cricket is the most popular sport.</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Watching vs. Participating preference:</strong><br>\n            Total watching = <span class=\"math\">1240 + 470 + 510 + 430 + 250 = <strong>2900</strong></span>.<br>\n            Total participating = <span class=\"math\">620 + 320 + 320 + 250 + 105 = <strong>1615</strong></span>.<br>\n            Since <span class=\"math\">2900 > 1615</span>, <strong>watching sports is preferred more</strong> than participating.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Identifying Cricket with total count</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Calculating totals (2900 vs 1615) &amp; conclusion</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_4_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_4_1')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">There are 6 marbles in a box with numbers from 1 to 6 marked on each of them.<br>(i) What is the probability of drawing a marble with number 2?<br>(ii) What is the probability of drawing a marble with number 5?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Sample Space:</strong><br>\n            Total number of marbles = <span class=\"math\">{1, 2, 3, 4, 5, 6} ⇒ n(S) = 6</span>.\n          </div>\n          <div class=\"step\">\n            <strong>(i) Probability of drawing marble number 2:</strong><br>\n            Number 2 appears on only 1 marble ⇒ n(E) = 1.<br>\n            <span class=\"math\">P(Number 2) = n(E)/n(S) = <strong>1/6</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Probability of drawing marble number 5:</strong><br>\n            Number 5 appears on only 1 marble ⇒ n(E) = 1.<br>\n            <span class=\"math\">P(Number 5) = n(E)/n(S) = <strong>1/6</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula P = Favourable / Total outcomes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Answers 1/6 for both parts</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Die Roll Outcomes</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> When a standard 6-faced die is thrown once, list the outcomes and find the probability of an event of getting: (i) a prime number, (ii) not a prime number, (iii) a number greater than 5, (iv) a number not greater than 5.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p>Total possible outcomes = <span class=\"math\">{1, 2, 3, 4, 5, 6}</span>, total = 6.</p>\n          <p><strong>(i) Prime number:</strong> Outcomes are <span class=\"math\">{2, 3, 5}</span> (3 outcomes) ⇒ P = 3/6 = <strong>1/2</strong>.</p>\n          <p><strong>(ii) Not a prime number:</strong> Outcomes are <span class=\"math\">{1, 4, 6}</span> (3 outcomes) ⇒ P = 3/6 = <strong>1/2</strong>. (Note: 1 is neither prime nor composite).</p>\n          <p><strong>(iii) Number greater than 5:</strong> Only <span class=\"math\">{6}</span> (1 outcome) ⇒ P = <strong>1/6</strong>.</p>\n          <p><strong>(iv) Number not greater than 5:</strong> Outcomes <span class=\"math\">{1, 2, 3, 4, 5}</span> (5 outcomes) ⇒ P = <strong>5/6</strong>.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(2)\">← Chapter 2: Fractions &amp; Decimals</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\">Chapter 4: Simple Equations →</button>\n  </div>\n</section>\n","4":"<section class=\"chapter-section\" id=\"ch4\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">4</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 4: Simple Equations</h2>\n      <p>NCERT Exercise 4.1 to 4.4 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Formulas Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Equation:</strong> A mathematical statement showing that two expressions have equal value (LHS = RHS), involving at least one variable.</li>\n      <li><strong>Solution of an Equation:</strong> The value of the variable for which the equation is satisfied (LHS = RHS).</li>\n      <li><strong>Rules for Balancing Equations:</strong>\n        <ul>\n          <li>Add or subtract the same number on both sides.</li>\n          <li>Multiply or divide both sides by the same non-zero number.</li>\n        </ul>\n      </li>\n      <li><strong>Transposition Method:</strong>\n        Moving a term from one side of the equation to the other changes its sign:\n        <ul>\n          <li>+  becomes  - &nbsp;|&nbsp; -  becomes  +</li>\n          <li>×  becomes  ÷ &nbsp;|&nbsp; ÷  becomes  ×</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 4.1 -->\n  <div class=\"ex-div\">Exercise 4.1</div>\n\n  <div class=\"q-card\" id=\"q4_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Check whether the value given in the brackets is a solution to the given equation or not:<br>(a) n + 5 = 19 (n = 1)<br>(b) 7n + 5 = 19 (n = −2)<br>(c) 7n + 5 = 19 (n = 2)<br>(d) 4p − 3 = 13 (p = 1)<br>(e) 4p − 3 = 13 (p = −4)<br>(f) 4p − 3 = 13 (p = 0)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) n + 5 = 19 for n = 1:</strong><br>\n            <span class=\"math\">LHS = 1 + 5 = 6 ≠ 19 (RHS) ⇒</span> <strong>No, not a solution.</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(b) 7n + 5 = 19 for n = −2:</strong><br>\n            <span class=\"math\">LHS = 7(−2) + 5 = −14 + 5 = −9 ≠ 19 (RHS) ⇒</span> <strong>No, not a solution.</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(c) 7n + 5 = 19 for n = 2:</strong><br>\n            <span class=\"math\">LHS = 7(2) + 5 = 14 + 5 = 19 = RHS ⇒</span> <strong>Yes, it is a solution.</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(d) 4p − 3 = 13 for p = 1:</strong><br>\n            <span class=\"math\">LHS = 4(1) − 3 = 4 − 3 = 1 ≠ 13 (RHS) ⇒</span> <strong>No, not a solution.</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(e) 4p − 3 = 13 for p = −4:</strong><br>\n            <span class=\"math\">LHS = 4(−4) − 3 = −16 − 3 = −19 ≠ 13 (RHS) ⇒</span> <strong>No, not a solution.</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(f) 4p − 3 = 13 for p = 0:</strong><br>\n            <span class=\"math\">LHS = 4(0) − 3 = −3 ≠ 13 (RHS) ⇒</span> <strong>No, not a solution.</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">LHS vs RHS evaluated for each part</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Write equations for the following statements:<br>(i) The sum of numbers x and 4 is 9.<br>(ii) 2 subtracted from y is 8.<br>(iii) Ten times a is 70.<br>(iv) The number b divided by 5 gives 6.<br>(v) Three-fourth of t is 15.<br>(vi) Seven times m plus 7 gets you 77.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">x + 4 = 9</span></strong><br>\n            <strong>(ii) <span class=\"math\">y − 2 = 8</span></strong><br>\n            <strong>(iii) <span class=\"math\">10a = 70</span></strong><br>\n            <strong>(iv) <span class=\"math\">b/5 = 6</span></strong><br>\n            <strong>(v) <span class=\"math\">3/4t = 15</span></strong><br>\n            <strong>(vi) <span class=\"math\">7m + 7 = 77</span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct algebraic equation translation</span><span class=\"marking-marks\">0.5 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 4.2 & 4.3 -->\n  <div class=\"ex-div\">Exercise 4.2 &amp; 4.3 (Solving Equations)</div>\n\n  <div class=\"q-card\" id=\"q4_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Solve the following equations:<br>(a) 2y + 5/2 = 37/2<br>(b) 5t + 28 = 10<br>(c) a/5 + 3 = 2<br>(d) q/4 + 7 = 5<br>(e) 5/2 x = −10<br>(f) 5/2 x = 25/4</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">2y + 5/2 = 37/2</span>:</strong><br>\n            Transpose <span class=\"math\">5/2</span>: <span class=\"math\">2y = 37/2 − 5/2 = 32/2 = 16 ⇒ y = 16/2 = <strong>8</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) <span class=\"math\">5t + 28 = 10</span>:</strong><br>\n            <span class=\"math\">5t = 10 − 28 = −18 ⇒ t = <strong>-18/5</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) <span class=\"math\">a/5 + 3 = 2</span>:</strong><br>\n            <span class=\"math\">a/5 = 2 − 3 = −1 ⇒ a = −1 × 5 = <strong>−5</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(d) <span class=\"math\">q/4 + 7 = 5</span>:</strong><br>\n            <span class=\"math\">q/4 = 5 − 7 = −2 ⇒ q = −2 × 4 = <strong>−8</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(e) <span class=\"math\">5/2x = −10</span>:</strong><br>\n            <span class=\"math\">x = −10 × 2/5 = −2 × 2 = <strong>−4</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(f) <span class=\"math\">5/2x = 25/4</span>:</strong><br>\n            <span class=\"math\">x = 25/4 × 2/5 = 5/2 = <strong>2 1/2</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct step-by-step solution</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_3_1')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Solve the following equations with brackets:<br>(a) 2(x + 4) = 12<br>(b) 3(n − 5) = 21<br>(c) 3(n − 5) = −21<br>(d) −4(2 + x) = 8<br>(e) 4(2 − x) = 8</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">2(x + 4) = 12</span>:</strong><br>\n            Divide both sides by 2: <span class=\"math\">x + 4 = 6 ⇒ x = 6 − 4 = <strong>2</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) <span class=\"math\">3(n − 5) = 21</span>:</strong><br>\n            Divide both sides by 3: <span class=\"math\">n − 5 = 7 ⇒ n = 7 + 5 = <strong>12</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) <span class=\"math\">3(n − 5) = −21</span>:</strong><br>\n            Divide both sides by 3: <span class=\"math\">n − 5 = −7 ⇒ n = −7 + 5 = <strong>−2</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(d) <span class=\"math\">−4(2 + x) = 8</span>:</strong><br>\n            Divide by −4: <span class=\"math\">2 + x = 8/(−4) = −2 ⇒ x = −2 − 2 = <strong>−4</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(e) <span class=\"math\">4(2 − x) = 8</span>:</strong><br>\n            Divide by 4: <span class=\"math\">2 − x = 2 ⇒ −x = 2 − 2 = 0 ⇒ <strong>x = 0</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Bracket expansion/division step &amp; solution</span><span class=\"marking-marks\">0.6 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 4.4 -->\n  <div class=\"ex-div\">Exercise 4.4 (Applications &amp; Word Problems)</div>\n\n  <div class=\"q-card\" id=\"q4_4_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_4_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Set up equations and solve them to find the unknown numbers:<br>(a) Add 4 to eight times a number; you get 60.<br>(b) One-fifth of a number minus 4 gives 3.<br>(c) If I take three-fourths of a number and add 3 to it, I get 21.<br>(d) When I subtracted 11 from twice a number, the result was 15.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> Let the number be <span class=\"math\">x</span>.<br>\n            Equation: <span class=\"math\">8x + 4 = 60 ⇒ 8x = 60 − 4 = 56 ⇒ x = 56/8 = <strong>7</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b)</strong> Let the number be <span class=\"math\">y</span>.<br>\n            Equation: <span class=\"math\">y/5 − 4 = 3 ⇒ y/5 = 7 ⇒ y = 7 × 5 = <strong>35</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(c)</strong> Let the number be <span class=\"math\">z</span>.<br>\n            Equation: <span class=\"math\">3/4z + 3 = 21 ⇒ 3/4z = 18 ⇒ z = 18 × 4/3 = 6 × 4 = <strong>24</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(d)</strong> Let the number be <span class=\"math\">n</span>.<br>\n            Equation: <span class=\"math\">2n − 11 = 15 ⇒ 2n = 15 + 11 = 26 ⇒ n = 26/2 = <strong>13</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Equation setup (0.5 Mark) + Solution (0.5 Mark)</span><span class=\"marking-marks\">1 Mark each (4 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_4_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_4_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Laxmi’s father is 49 years old. He is 4 years older than three times Laxmi’s age. What is Laxmi’s age?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Define variable:</strong><br>\n            Let Laxmi's present age be <span class=\"math\">y years</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Set up equation:</strong><br>\n            Three times Laxmi's age = <span class=\"math\">3y</span>.<br>\n            Father is 4 years older than <span class=\"math\">3y</span>: <span class=\"math\">3y + 4</span>.<br>\n            Given father's age is 49 years:<br>\n            <span class=\"math\">3y + 4 = 49</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Solve for y:</strong><br>\n            <span class=\"math\">3y = 49 − 4 = 45 ⇒ y = 45/3 = <strong>15</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> Laxmi’s age is <strong>15 years</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Assuming variable and equation 3y + 4 = 49</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving y = 15 with final conclusion statement</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_4_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_4_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Irfan says that he has 7 marbles more than five times the marbles Parmit has. Irfan has 37 marbles. How many marbles does Parmit have?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Define variable:</strong><br>\n            Let the number of marbles Parmit has be <span class=\"math\">m</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Form equation:</strong><br>\n            Five times Parmit's marbles = <span class=\"math\">5m</span>.<br>\n            7 marbles more than 5m = <span class=\"math\">5m + 7</span>.<br>\n            Given Irfan has 37 marbles:<br>\n            <span class=\"math\">5m + 7 = 37</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Solve equation:</strong><br>\n            <span class=\"math\">5m = 37 − 7 = 30 ⇒ m = 30/5 = <strong>6</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> Parmit has <strong>6 marbles</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Forming equation 5m + 7 = 37</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for m = 6 with statement</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Cricket Partnership</div>\n        <div class=\"cbq-question\"><strong>Scenario:</strong> Rahul scored twice as many runs as Sachin. Together, their runs fell two short of a double century (200 runs). (i) Form an equation to represent this situation. (ii) How many runs did each one score?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Equation Formulation:</strong><br>\n          Let Sachin's score = <span class=\"math\">x</span> runs.<br>\n          Rahul's score = <span class=\"math\">2x</span> runs.<br>\n          Combined runs = <span class=\"math\">x + 2x = 3x</span>.<br>\n          Two short of a double century = <span class=\"math\">200 − 2 = 198</span>.<br>\n          Equation: <span class=\"math\"><strong>3x = 198</strong></span>.</p>\n          <p><strong>(ii) Solving for individual scores:</strong><br>\n          <span class=\"math\">x = 198/3 = <strong>66</strong></span>.<br>\n          Sachin scored = <strong>66 runs</strong>.<br>\n          Rahul scored = <span class=\"math\">2 × 66 = <strong>132 runs</strong></span>.<br>\n          Check: <span class=\"math\">66 + 132 = 198</span> (verified).</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(3)\">← Chapter 3: Data Handling</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\">Chapter 5: Lines &amp; Angles →</button>\n  </div>\n</section>\n","5":"<section class=\"chapter-section\" id=\"ch5\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">5</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 5: Lines and Angles</h2>\n      <p>NCERT Exercise 5.1 to 5.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Angle Properties Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Complementary Angles:</strong> Two angles whose sum of measures equals 90°. Each angle is called the complement of the other.</li>\n      <li><strong>Supplementary Angles:</strong> Two angles whose sum of measures equals 180°. Each angle is called the supplement of the other.</li>\n      <li><strong>Adjacent Angles:</strong> Angles that have a common vertex, a common arm, and non-common arms on opposite sides of the common arm.</li>\n      <li><strong>Linear Pair:</strong> A pair of adjacent angles whose non-common sides form opposite rays (a straight line). Sum = 180°.</li>\n      <li><strong>Vertically Opposite Angles:</strong> When two lines intersect at a point, vertically opposite angles are formed and are always equal.</li>\n      <li><strong>Parallel Lines and Transversal:</strong>\n        When two parallel lines l ∥ m are cut by a transversal t:\n        <ul>\n          <li><em>Corresponding angles</em> are equal (∠ 1 = ∠ 5, etc.).</li>\n          <li><em>Alternate interior angles</em> are equal (∠ 3 = ∠ 5, ∠ 4 = ∠ 6).</li>\n          <li><em>Alternate exterior angles</em> are equal (∠ 1 = ∠ 7, ∠ 2 = ∠ 8).</li>\n          <li><em>Co-interior angles</em> (interior angles on same side of transversal) are supplementary (∠ 4 + ∠ 5 = 180°).</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 5.1 -->\n  <div class=\"ex-div\">Exercise 5.1</div>\n\n  <div class=\"q-card\" id=\"q5_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the complement of each of the following angles:<br>(i) 20°<br>(ii) 63°<br>(iii) 57°</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Two angles are complementary if their sum is <span class=\"math\">90°</span>. The complement of <span class=\"math\">θ = 90° − θ</span>.</p>\n          <div class=\"step\">\n            <strong>(i) Complement of 20°:</strong><br>\n            <span class=\"math\">= 90° − 20° = <strong>70°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Complement of 63°:</strong><br>\n            <span class=\"math\">= 90° − 63° = <strong>27°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) Complement of 57°:</strong><br>\n            <span class=\"math\">= 90° − 57° = <strong>33°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct complement subtraction</span><span class=\"marking-marks\">1 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the supplement of each of the following angles:<br>(i) 105°<br>(ii) 87°<br>(iii) 154°</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Two angles are supplementary if their sum is <span class=\"math\">180°</span>. The supplement of <span class=\"math\">θ = 180° − θ</span>.</p>\n          <div class=\"step\">\n            <strong>(i) Supplement of 105°:</strong><br>\n            <span class=\"math\">= 180° − 105° = <strong>75°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Supplement of 87°:</strong><br>\n            <span class=\"math\">= 180° − 87° = <strong>93°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) Supplement of 154°:</strong><br>\n            <span class=\"math\">= 180° − 154° = <strong>26°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct supplement calculation</span><span class=\"marking-marks\">1 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Identify which of the following pairs of angles are complementary and which are supplementary:<br>(i) 65°, 115°<br>(ii) 63°, 27°<br>(iii) 112°, 68°<br>(iv) 130°, 50°<br>(v) 45°, 45°<br>(vi) 80°, 10°</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 65° + 115° = 180°:</strong> ⇒ <strong>Supplementary</strong>.<br>\n            <strong>(ii) 63° + 27° = 90°:</strong> ⇒ <strong>Complementary</strong>.<br>\n            <strong>(iii) 112° + 68° = 180°:</strong> ⇒ <strong>Supplementary</strong>.<br>\n            <strong>(iv) 130° + 50° = 180°:</strong> ⇒ <strong>Supplementary</strong>.<br>\n            <strong>(v) 45° + 45° = 90°:</strong> ⇒ <strong>Complementary</strong>.<br>\n            <strong>(vi) 80° + 10° = 90°:</strong> ⇒ <strong>Complementary</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct sum and classification</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">(a) Find the angle which is equal to its complement.<br>(b) Find the angle which is equal to its supplement.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Angle equal to its complement:</strong><br>\n            Let the angle be <span class=\"math\">x</span>.<br>\n            Its complement is <span class=\"math\">90° − x</span>.<br>\n            According to question: <span class=\"math\">x = 90° − x ⇒ 2x = 90° ⇒ x = <strong>45°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) Angle equal to its supplement:</strong><br>\n            Let the angle be <span class=\"math\">y</span>.<br>\n            Its supplement is <span class=\"math\">180° − y</span>.<br>\n            According to question: <span class=\"math\">y = 180° − y ⇒ 2y = 180° ⇒ y = <strong>90°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): Equation 2x = 90° and x = 45°</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): Equation 2y = 180° and y = 90°</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Two lines intersect at a point. If one angle is 55°, find the values of all other angles x, y and z.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Vertically opposite angle:</strong><br>\n            Angle <span class=\"math\">x</span> is vertically opposite to 55°.<br>\n            Therefore, <span class=\"math\">x = <strong>55°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Linear pair:</strong><br>\n            Angle <span class=\"math\">y</span> and 55° form a linear pair on a straight line:<br>\n            <span class=\"math\">y + 55° = 180° ⇒ y = 180° − 55° = <strong>125°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Vertically opposite to y:</strong><br>\n            Angle <span class=\"math\">z</span> is vertically opposite to <span class=\"math\">y</span>:<br>\n            <span class=\"math\">z = y = <strong>125°</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> <span class=\"math\">x = 55°</span>, <span class=\"math\">y = 125°</span>, <span class=\"math\">z = 125°</span>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">x = 55° with vertically opposite angle reason</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">y = 125° with linear pair equation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">z = 125° with vertically opposite reason</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 5.2 -->\n  <div class=\"ex-div\">Exercise 5.2 (Parallel Lines &amp; Transversal)</div>\n\n  <div class=\"q-card\" id=\"q5_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">In a given figure, lines l ∥ m are cut by transversal p. If one exterior angle is 125°, find the measures of remaining angles a, b, c, d, e, f.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Linear pair with 125°:</strong><br>\n            <span class=\"math\">e + 125° = 180° ⇒ e = 180° − 125° = <strong>55°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Vertically opposite angles:</strong><br>\n            <span class=\"math\">f = e = <strong>55°</strong></span>.<br>\n            Angle opposite to 125° is <span class=\"math\">125°</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Corresponding angles (since l ∥ m):</strong><br>\n            <span class=\"math\">d = 125°</span> (corresponding to 125°).<br>\n            <span class=\"math\">a = e = <strong>55°</strong></span> (corresponding to e).<br>\n            <span class=\"math\">b = d = <strong>125°</strong></span> (vertically opposite to d).<br>\n            <span class=\"math\">c = a = <strong>55°</strong></span> (vertically opposite to a).\n          </div>\n          <p><strong>Final Answer:</strong> <span class=\"math\">a = 55°</span>, <span class=\"math\">b = 125°</span>, <span class=\"math\">c = 55°</span>, <span class=\"math\">d = 125°</span>, <span class=\"math\">e = 55°</span>, <span class=\"math\">f = 55°</span>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Linear pair to find e = 55°</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Corresponding angle arguments for d, a</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vertically opposite arguments for b, c, f</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the value of x in each of the following figures if l ∥ m:<br>(i) One angle is 110° and alternate interior to x with linear pair.<br>(ii) Co-interior angles are (2x)° and (3x)°.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Figure with angle 110°:</strong><br>\n            The angle adjacent to 110° on the straight line is: <span class=\"math\">180° − 110° = 70°</span>.<br>\n            Since <span class=\"math\">l ∥ m</span>, angle <span class=\"math\">x</span> is corresponding (or alternate) to this angle:<br>\n            <span class=\"math\">x = 180° − 110° = <strong>70°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Co-interior angles 2x and 3x:</strong><br>\n            Interior angles on the same side of a transversal are supplementary:<br>\n            <span class=\"math\">2x + 3x = 180° ⇒ 5x = 180° ⇒ x = 180°/5 = <strong>36°</strong></span>.<br>\n            The angles are <span class=\"math\">2(36°) = 72°</span> and <span class=\"math\">3(36°) = 108°</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Linear pair / corresponding reasoning x = 70°</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Co-interior angles sum = 180° and x = 36°</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Ratio of Supplementary Angles</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> Two supplementary angles are in the ratio 4 : 5. Find the measure of both angles.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p>Let the common ratio multiplier be <span class=\"math\">x</span>.<br>\n          The two angles are <span class=\"math\">4x</span> and <span class=\"math\">5x</span>.<br>\n          Since they are supplementary:<br>\n          <span class=\"math\">4x + 5x = 180° ⇒ 9x = 180° ⇒ x = 180°/9 = 20°</span>.<br>\n          First angle = <span class=\"math\">4 × 20° = <strong>80°</strong></span>.<br>\n          Second angle = <span class=\"math\">5 × 20° = <strong>100°</strong></span>.<br>\n          Check: <span class=\"math\">80° + 100° = 180°</span> (verified).</p>\n        </div>\n      </div>\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#10b981;\">⚡ Assertion &amp; Reason</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> If two parallel lines are intersected by a transversal, then each pair of alternate interior angles are equal.<br>\n          <strong>Reason (R):</strong> If two parallel lines are intersected by a transversal, the interior angles on the same side of the transversal are supplementary.<br>\n          Choose: (a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true, but R is not the correct explanation of A. (c) A is true, R is false. (d) A is false, R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <strong>Answer: (b) Both A and R are true, but R is not the correct explanation of A.</strong><br>\n          <em>Explanation:</em> Both statements are fundamental, correct geometric properties of parallel lines and transversals, but Reason (R) states the co-interior angle property, which is not the explanation for why alternate interior angles are equal.\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(4)\">← Chapter 4: Simple Equations</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\">Chapter 6: Triangle &amp; its Properties →</button>\n  </div>\n</section>\n","6":"<section class=\"chapter-section\" id=\"ch6\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">6</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 6: The Triangle and its Properties</h2>\n      <p>NCERT Exercise 6.1 to 6.5 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Theorems Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Median of a Triangle:</strong> The line segment connecting a vertex to the midpoint of the opposite side. Every triangle has 3 medians that concur at the <em>Centroid</em>.</li>\n      <li><strong>Altitude of a Triangle:</strong> The perpendicular line segment from a vertex to the line containing the opposite side. A triangle has 3 altitudes that concur at the <em>Orthocentre</em>.</li>\n      <li><strong>Exterior Angle Property:</strong> An exterior angle of a triangle is equal to the sum of its two interior opposite angles:\n        ∠ ext = ∠ A + ∠ B\n      </li>\n      <li><strong>Angle Sum Property:</strong> The sum of all three interior angles of a triangle is always 180°:\n        ∠ A + ∠ B + ∠ C = 180°\n      </li>\n      <li><strong>Triangle Inequality Property:</strong> The sum of the lengths of any two sides of a triangle is always greater than the length of the third side:\n        a + b > c,   b + c > a,   c + a > b\n      </li>\n      <li><strong>Pythagoras Theorem:</strong> In a right-angled triangle, the square of the hypotenuse is equal to the sum of the squares of the other two sides:\n        Hypotenuse² = Base² + Perpendicular² ⇒ h² = b² + p²\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 6.1 -->\n  <div class=\"ex-div\">Exercise 6.1</div>\n\n  <div class=\"q-card\" id=\"q6_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">In ΔPQR, D is the mid-point of QR. (i) Line segment PM is ..... (ii) Line segment PD is ..... (iii) Is QM = MR?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Line segment PM:</strong><br>\n            Since <span class=\"math\">PM ⊥ QR</span> (makes a right angle 90° with QR), <span class=\"math\">PM</span> is an <strong>Altitude</strong> of ΔPQR.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Line segment PD:</strong><br>\n            Since D is the midpoint of QR, line segment joining vertex P to midpoint D is the <strong>Median</strong> of ΔPQR.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) Is QM = MR?</strong><br>\n            <strong>No, QM ≠ MR.</strong> Because D is the midpoint (so <span class=\"math\">QD = DR</span>), whereas M is the foot of the perpendicular altitude, which is not necessarily the midpoint for a scalene triangle.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Altitude</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Median</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) No, with justification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 6.2 -->\n  <div class=\"ex-div\">Exercise 6.2 (Exterior Angle Property)</div>\n\n  <div class=\"q-card\" id=\"q6_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the value of the unknown exterior angle x in the following figures:<br>(i) Interior opposite angles are 50° and 70°<br>(ii) Interior opposite angles are 65° and 45°<br>(iii) Interior opposite angles are 30° and 40°</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>By Exterior Angle Property: <span class=\"math\">Exterior angle = Sum of interior opposite angles</span>.</p>\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">x = 50° + 70° = <strong>120°</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">x = 65° + 45° = <strong>110°</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">x = 30° + 40° = <strong>70°</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Exterior angle formula statement</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation</span><span class=\"marking-marks\">0.67 Mark each (2 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the value of the unknown interior angle x in the following figures:<br>(i) Exterior angle = 115°, one interior opposite angle = 50°<br>(ii) Exterior angle = 100°, one interior opposite angle = 70°<br>(iii) Exterior angle = 125°, right angled at other interior opposite angle (90°)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">x + 50° = 115° ⇒ x = 115° − 50° = <strong>65°</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">x + 70° = 100° ⇒ x = 100° − 70° = <strong>30°</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">x + 90° = 125° ⇒ x = 125° − 90° = <strong>35°</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct subtraction from exterior angle</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 6.3 -->\n  <div class=\"ex-div\">Exercise 6.3 (Angle Sum Property)</div>\n\n  <div class=\"q-card\" id=\"q6_3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the value of the unknown x in the following triangles:<br>(i) Two angles are 50° and 60°<br>(ii) Right-angled triangle with one acute angle 30°<br>(iii) Two angles are 30° and 110°<br>(iv) Isosceles triangle with two equal angles x and vertex angle 50°<br>(v) Equilateral-like triangle with all angles equal to x</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>By Angle Sum Property of a triangle: <span class=\"math\">Sum of all 3 angles = 180°</span>.</p>\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">x + 50° + 60° = 180° ⇒ x + 110° = 180° ⇒ x = <strong>70°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii)</strong> <span class=\"math\">x + 90° + 30° = 180° ⇒ x + 120° = 180° ⇒ x = <strong>60°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii)</strong> <span class=\"math\">x + 30° + 110° = 180° ⇒ x + 140° = 180° ⇒ x = <strong>40°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv)</strong> <span class=\"math\">x + x + 50° = 180° ⇒ 2x = 180° − 50° = 130° ⇒ x = 130°/2 = <strong>65°</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(v)</strong> <span class=\"math\">x + x + x = 180° ⇒ 3x = 180° ⇒ x = 180°/3 = <strong>60°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating Angle Sum Property = 180°</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurately computed angle values</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 6.4 -->\n  <div class=\"ex-div\">Exercise 6.4 (Triangle Inequality)</div>\n\n  <div class=\"q-card\" id=\"q6_4_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_4_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Is it possible to have a triangle with the following sides?<br>(i) 2 cm, 3 cm, 5 cm<br>(ii) 3 cm, 6 cm, 7 cm<br>(iii) 6 cm, 3 cm, 2 cm</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Property:</strong> In any triangle, the sum of lengths of any two sides must be strictly greater than the third side (<span class=\"math\">a + b > c</span>).</p>\n          <div class=\"step\">\n            <strong>(i) 2 cm, 3 cm, 5 cm:</strong><br>\n            Check sum of smaller sides: <span class=\"math\">2 + 3 = 5 cm</span>.<br>\n            Since <span class=\"math\">5</span> is not greater than the third side <span class=\"math\">5</span> (<span class=\"math\">5 = 5</span>), <strong>a triangle is NOT possible</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) 3 cm, 6 cm, 7 cm:</strong><br>\n            Check all three combinations:<br>\n            • <span class=\"math\">3 + 6 = 9 > 7</span> (True)<br>\n            • <span class=\"math\">6 + 7 = 13 > 3</span> (True)<br>\n            • <span class=\"math\">3 + 7 = 10 > 6</span> (True)<br>\n            Therefore, <strong>a triangle IS possible</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) 6 cm, 3 cm, 2 cm:</strong><br>\n            Check sum of smaller sides: <span class=\"math\">3 + 2 = 5 cm</span>.<br>\n            Since <span class=\"math\">5 < 6</span> (less than third side), <strong>a triangle is NOT possible</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part checked against a + b > c with clear decision</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_4_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_4_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">The lengths of two sides of a triangle are 12 cm and 15 cm. Between what two measures should the length of the third side fall?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Mathematical Principle:</strong><br>\n            For any triangle with sides <span class=\"math\">a, b, c</span>:<br>\n            <span class=\"math\">|a − b| < c < (a + b)</span>.<br>\n            That is, the third side must be greater than the difference of the two sides and less than their sum.\n          </div>\n          <div class=\"step\">\n            <strong>Calculation:</strong><br>\n            Sum of two sides = <span class=\"math\">15 + 12 = <strong>27 cm</strong></span>.<br>\n            Difference of two sides = <span class=\"math\">15 − 12 = <strong>3 cm</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The length of the third side must be greater than <strong>3 cm</strong> and less than <strong>27 cm</strong> (i.e. between 3 cm and 27 cm).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Difference bound: 15 − 12 = 3 cm</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sum bound: 15 + 12 = 27 cm with final statement</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 6.5 -->\n  <div class=\"ex-div\">Exercise 6.5 (Pythagoras Theorem)</div>\n\n  <div class=\"q-card\" id=\"q6_5_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">PQR is a triangle, right-angled at P. If PQ = 10 cm and PR = 24 cm, find QR.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Identify sides of right-angled triangle:</strong><br>\n            Right angle is at vertex P ⇒ QR is the <strong>hypotenuse</strong>.<br>\n            Given legs: <span class=\"math\">PQ = 10 cm</span>, <span class=\"math\">PR = 24 cm</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Apply Pythagoras Theorem:</strong><br>\n            <span class=\"math\">QR² = PQ² + PR²</span><br>\n            <span class=\"math\">QR² = 10² + 24² = 100 + 576 = 676</span><br>\n            <span class=\"math\">QR = √(676) = <strong>26 cm</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The length of <span class=\"math\">QR</span> is <strong>26 cm</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras formula: QR² = PQ² + PR²</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">10² + 24² = 676</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">QR = 26 cm with unit</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_5_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">A 15 m long ladder reached a window 12 m high from the ground on placing it against a wall at a distance a. Find the distance of the foot of the ladder from the wall.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Geometry setup:</strong><br>\n            The wall and the horizontal ground meet at 90°.<br>\n            Ladder acts as hypotenuse: <span class=\"math\">h = 15 m</span>.<br>\n            Height of window: <span class=\"math\">p = 12 m</span>.<br>\n            Distance of foot from wall: <span class=\"math\">b = a</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Pythagoras Theorem:</strong><br>\n            <span class=\"math\">a² + 12² = 15²</span><br>\n            <span class=\"math\">a² + 144 = 225</span><br>\n            <span class=\"math\">a² = 225 − 144 = 81</span><br>\n            <span class=\"math\">a = √(81) = <strong>9 m</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The distance of the foot of the ladder from the wall is <strong>9 metres</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras setup: a² + 12² = 15²</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">a² = 81 evaluation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer a = 9 m with unit</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_5_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">A tree is broken at a height of 5 m from the ground and its top touches the ground at a distance of 12 m from the base of the tree. Find the original height of the tree.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Right-angled triangle model:</strong><br>\n            Let <span class=\"math\">BC = 5 m</span> be the standing trunk (perpendicular).<br>\n            Distance from trunk base to top <span class=\"math\">AB = 12 m</span> (base).<br>\n            The broken fallen trunk <span class=\"math\">AC</span> is the hypotenuse.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Calculate hypotenuse AC:</strong><br>\n            <span class=\"math\">AC² = AB² + BC² = 12² + 5² = 144 + 25 = 169</span><br>\n            <span class=\"math\">AC = √(169) = 13 m</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Calculate original tree height:</strong><br>\n            <span class=\"math\">Original height = BC + AC = 5 m + 13 m = <strong>18 m</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The original height of the tree was <strong>18 metres</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras theorem: AC = 13 m</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Adding 5 m + 13 m = 18 m with conclusion</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_5_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Find the perimeter of the rectangle whose length is 40 cm and a diagonal is 41 cm.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Find breadth using Pythagoras theorem:</strong><br>\n            In a rectangle, adjacent sides meet at 90°. Diagonal = <span class=\"math\">41 cm</span>, Length = <span class=\"math\">40 cm</span>.<br>\n            <span class=\"math\">Breadth² + 40² = 41²</span><br>\n            <span class=\"math\">b² + 1600 = 1681 ⇒ b² = 1681 − 1600 = 81 ⇒ b = √(81) = <strong>9 cm</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Calculate perimeter:</strong><br>\n            <span class=\"math\">Perimeter = 2(l + b) = 2(40 + 9) = 2 × 49 = <strong>98 cm</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The perimeter of the rectangle is <strong>98 cm</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras theorem to find breadth b = 9 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Perimeter = 2(40 + 9) = 98 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Perimeter of Rhombus via Diagonals</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> The diagonals of a rhombus measure 16 cm and 30 cm. Find its perimeter.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Properties of Rhombus:</strong><br>\n          1. Diagonals bisect each other at right angles (90°).<br>\n          Half of diagonal 1 = <span class=\"math\">16/2 = 8 cm</span>.<br>\n          Half of diagonal 2 = <span class=\"math\">30/2 = 15 cm</span>.<br>\n          2. In right-angled triangle formed by half-diagonals and side <span class=\"math\">s</span>:<br>\n          <span class=\"math\">s² = 8² + 15² = 64 + 225 = 289 ⇒ s = √(289) = <strong>17 cm</strong></span>.<br>\n          3. <span class=\"math\">Perimeter of rhombus = 4 × s = 4 × 17 = <strong>68 cm</strong></span>.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(5)\">← Chapter 5: Lines &amp; Angles</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\">Chapter 7: Comparing Quantities →</button>\n  </div>\n</section>\n","7":"<section class=\"chapter-section\" id=\"ch7\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">7</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 7: Comparing Quantities</h2>\n      <p>NCERT Exercise 7.1 to 7.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Commercial Mathematics Formulas</div>\n    <ul class=\"concept-list\">\n      <li><strong>Ratio:</strong> A comparison of two quantities of the same kind by division (a : b = a/b). Both quantities must have the same unit.</li>\n      <li><strong>Percentage:</strong> Ratios with denominator 100.\n        <ul>\n          <li>Fraction/Decimal to % ⇒ Multiply by 100%.</li>\n          <li>%  to Fraction/Decimal ⇒ Divide by 100.</li>\n        </ul>\n      </li>\n      <li><strong>Percentage Change:</strong>\n        Percentage Increase / Decrease = (Amount of change)/(Original value) × 100%\n      </li>\n      <li><strong>Profit and Loss:</strong>\n        <ul>\n          <li>When SP > CP ⇒ Profit = SP - CP; Profit  % = Profit/CP × 100%.</li>\n          <li>When CP > SP ⇒ Loss = CP - SP; Loss  % = Loss/CP × 100%.</li>\n        </ul>\n      </li>\n      <li><strong>Simple Interest:</strong>\n        SI = (P × R × T)/100,   Total Amount  A = P + SI\n        where P = Principal (sum borrowed/invested), R = Rate of interest per annum, T = Time in years.\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 7.1 -->\n  <div class=\"ex-div\">Exercise 7.1 (Ratios &amp; Percentages)</div>\n\n  <div class=\"q-card\" id=\"q7_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the ratio of:<br>(a) ₹5 to 50 paise<br>(b) 15 kg to 210 g<br>(c) 9 m to 27 cm<br>(d) 30 days to 36 hours</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) ₹5 to 50 paise:</strong><br>\n            Convert to paise: <span class=\"math\">₹5 = 5 × 100 = 500 paise</span>.<br>\n            Ratio = <span class=\"math\">500/50 = 10/1 = <strong>10 : 1</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) 15 kg to 210 g:</strong><br>\n            Convert to grams: <span class=\"math\">15 kg = 15 × 1000 = 15000 g</span>.<br>\n            Ratio = <span class=\"math\">15000/210 = 1500/21 = 500/7 = <strong>500 : 7</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) 9 m to 27 cm:</strong><br>\n            Convert to cm: <span class=\"math\">9 m = 900 cm</span>.<br>\n            Ratio = <span class=\"math\">900/27 = 100/3 = <strong>100 : 3</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(d) 30 days to 36 hours:</strong><br>\n            Convert to hours: <span class=\"math\">30 days = 30 × 24 = 720 hours</span>.<br>\n            Ratio = <span class=\"math\">720/36 = 20/1 = <strong>20 : 1</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Unit conversions done accurately</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">All ratios simplified to lowest terms</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">In a computer lab, there are 3 computers for every 6 students. How many computers will be needed for 24 students?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Unitary Method:</strong><br>\n            Computers required for 6 students = 3.<br>\n            Computers required for 1 student = <span class=\"math\">3/6 = 1/2</span>.\n          </div>\n          <div class=\"step\">\n            Computers required for 24 students = <span class=\"math\">24 × 1/2 = <strong>12 computers</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> Exactly <strong>12 computers</strong> will be needed for 24 students.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rate for 1 student = 3/6 = 1/2</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total computers = 24 × 1/2 = 12</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Convert the given fractional numbers to per cents:<br>(a) 1/8<br>(b) 5/4<br>(c) 3/40<br>(d) 2/7</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">1/8 × 100% = 25/2% = <strong>12.5%</strong> = <strong>12 1/2%</strong></span></strong><br>\n            <strong>(b) <span class=\"math\">5/4 × 100% = 5 × 25% = <strong>125%</strong></span></strong><br>\n            <strong>(c) <span class=\"math\">3/40 × 100% = 15/2% = <strong>7.5%</strong></span></strong><br>\n            <strong>(d) <span class=\"math\">2/7 × 100% = 200/7% = <strong>28 4/7%</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each fraction converted to %</span><span class=\"marking-marks\">0.5 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Find:<br>(a) 15% of 250<br>(b) 1% of 1 hour<br>(c) 20% of ₹2500<br>(d) 75% of 1 kg</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">15%  of  250 = 15/100 × 250 = (15 × 5)/2 = 75/2 = <strong>37.5</strong></span></strong><br>\n            <strong>(b) <span class=\"math\">1%  of  1 hour = 1/100 × 60 min = (60 × 60)/100 sec = <strong>36 seconds</strong></span></strong><br>\n            <strong>(c) <span class=\"math\">20%  of  ₹2500 = 20/100 × 2500 = 20 × 25 = <strong>₹500</strong></span></strong><br>\n            <strong>(d) <span class=\"math\">75%  of  1 kg = 75/100 × 1000 g = 75 × 10 = <strong>750 g</strong> = <strong>0.75 kg</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct percentage evaluation</span><span class=\"marking-marks\">0.5 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 7.2 -->\n  <div class=\"ex-div\">Exercise 7.2 (Profit &amp; Loss, Simple Interest)</div>\n\n  <div class=\"q-card\" id=\"q7_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Tell what is the profit or loss in the following transactions. Also find profit per cent or loss per cent in each case:<br>(a) Gardening shears bought for ₹250 and sold for ₹325.<br>(b) A refrigerator bought for ₹12,000 and sold at ₹13,500.<br>(c) A cupboard bought for ₹2,500 and sold at ₹3,000.<br>(d) A skirt bought for ₹250 and sold at ₹150.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Gardening shears:</strong><br>\n            <span class=\"math\">CP = ₹250, SP = ₹325</span>. Since <span class=\"math\">SP > CP</span>, there is a profit.<br>\n            <span class=\"math\">Profit = 325 − 250 = <strong>₹75</strong></span>.<br>\n            <span class=\"math\">Profit  % = 75/250 × 100 = 3/10 × 100 = <strong>30%</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) Refrigerator:</strong><br>\n            <span class=\"math\">CP = ₹12,000, SP = ₹13,500</span>. Profit.<br>\n            <span class=\"math\">Profit = 13500 − 12000 = <strong>₹1,500</strong></span>.<br>\n            <span class=\"math\">Profit  % = 1500/12000 × 100 = 150/12 = <strong>12.5%</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) Cupboard:</strong><br>\n            <span class=\"math\">CP = ₹2,500, SP = ₹3,000</span>. Profit.<br>\n            <span class=\"math\">Profit = 3000 − 2500 = <strong>₹500</strong></span>.<br>\n            <span class=\"math\">Profit  % = 500/2500 × 100 = 1/5 × 100 = <strong>20%</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(d) Skirt:</strong><br>\n            <span class=\"math\">CP = ₹250, SP = ₹150</span>. Since <span class=\"math\">CP > SP</span>, there is a loss.<br>\n            <span class=\"math\">Loss = 250 − 150 = <strong>₹100</strong></span>.<br>\n            <span class=\"math\">Loss  % = 100/250 × 100 = 2/5 × 100 = <strong>40%</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Profit/Loss calculation (0.5 Mark) + % calculation (0.5 Mark)</span><span class=\"marking-marks\">1 Mark each (4 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the amount to be paid at the end of 3 years in each case:<br>(a) Principal = ₹1,200 at 12% p.a.<br>(b) Principal = ₹7,500 at 5% p.a.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) P = ₹1,200, R = 12% p.a., T = 3 years:</strong><br>\n            <span class=\"math\">SI = (P × R × T)/100 = (1200 × 12 × 3)/100 = 12 × 36 = <strong>₹432</strong></span>.<br>\n            <span class=\"math\">Amount = P + SI = ₹1200 + ₹432 = <strong>₹1,632</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) P = ₹7,500, R = 5% p.a., T = 3 years:</strong><br>\n            <span class=\"math\">SI = (P × R × T)/100 = (7500 × 5 × 3)/100 = 75 × 15 = <strong>₹1,125</strong></span>.<br>\n            <span class=\"math\">Amount = P + SI = ₹7500 + ₹1125 = <strong>₹8,625</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): SI = ₹432, Amount = ₹1,632</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): SI = ₹1,125, Amount = ₹8,625</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">What rate gives ₹280 as interest on a sum of ₹56,000 in 2 years?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Given:</strong><br>\n            <span class=\"math\">SI = ₹280</span>, <span class=\"math\">P = ₹56,000</span>, <span class=\"math\">T = 2 years</span>.\n          </div>\n          <div class=\"step\">\n            <strong>Formula for Rate:</strong><br>\n            <span class=\"math\">R = (SI × 100)/(P × T) = (280 × 100)/(56000 × 2) = 28000/112000 = 28/112 = 1/4% = <strong>0.25%</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The rate of interest is <strong>0.25% (or ¼%) per annum</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula R = (SI × 100) / (P × T)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">R = 0.25% p.a. with statement</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Population Growth &amp; Depreciation</div>\n        <div class=\"cbq-question\"><strong>Scenario:</strong> The population of a city decreased from 25,000 to 24,500. (i) Find the percentage decrease in population. (ii) If the population decreases by the same percentage next year, what will the new population be?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Percentage decrease:</strong><br>\n          Original population = <span class=\"math\">25,000</span>.<br>\n          Decrease = <span class=\"math\">25,000 − 24,500 = 500</span>.<br>\n          <span class=\"math\">Percentage Decrease = 500/25000 × 100% = 50/25% = <strong>2%</strong></span>.</p>\n          <p><strong>(ii) Next year's population:</strong><br>\n          Decrease next year = <span class=\"math\">2%  of  24,500 = 2/100 × 24500 = 490</span>.<br>\n          New population = <span class=\"math\">24,500 − 490 = <strong>24,010</strong></span>.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(6)\">← Chapter 6: Triangle &amp; its Properties</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\">Chapter 8: Rational Numbers →</button>\n  </div>\n</section>\n","8":"<section class=\"chapter-section\" id=\"ch8\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">8</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 8: Rational Numbers</h2>\n      <p>NCERT Exercise 8.1 to 8.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Properties Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Rational Number:</strong> A number that can be written in the form p/q, where p and q are integers and q ≠ 0.\n        <ul>\n          <li><em>Positive:</em> Both p and q have the same sign (e.g. 2/3, (-5)/(-7)).</li>\n          <li><em>Negative:</em> p and q have opposite signs (e.g. (-3)/8, 5/(-9)).</li>\n          <li>0 is a rational number since 0 = 0/1.</li>\n        </ul>\n      </li>\n      <li><strong>Standard Form:</strong> A rational number p/q is in standard form if q > 0 and p, q have no common factor other than 1.</li>\n      <li><strong>Equivalent Rational Numbers:</strong> Obtained by multiplying or dividing numerator and denominator by the same non-zero integer:\n        p/q = (p × m)/(q × m)\n      </li>\n      <li><strong>Density Property:</strong> Between any two rational numbers, there exist infinitely many rational numbers.</li>\n      <li><strong>Operations on Rational Numbers:</strong>\n        <ul>\n          <li><em>Addition/Subtraction:</em> Take LCM of denominators and adjust numerators accordingly.</li>\n          <li><em>Multiplication:</em> a/b × c/d = (a × c)/(b × d).</li>\n          <li><em>Division:</em> a/b ÷ c/d = a/b × d/c (multiplication by reciprocal of divisor).</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 8.1 -->\n  <div class=\"ex-div\">Exercise 8.1</div>\n\n  <div class=\"q-card\" id=\"q8_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">List five rational numbers between:<br>(i) −1 and 0<br>(ii) −2 and −1<br>(iii) −4/5 and −2/3<br>(iv) −1/2 and 2/3</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Between −1 and 0:</strong><br>\n            Multiply numerator and denominator by <span class=\"math\">5 + 1 = 6</span>:<br>\n            <span class=\"math\">−1 = -6/6</span>, &nbsp; <span class=\"math\">0 = 0/6</span>.<br>\n            Five rational numbers: <span class=\"math\"><strong>-5/6, -4/6, -3/6, -2/6, -1/6</strong></span><br>\n            (Simplified: <span class=\"math\">-5/6, -2/3, -1/2, -1/3, -1/6</span>).\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Between −2 and −1:</strong><br>\n            Multiply by 6:<br>\n            <span class=\"math\">−2 = -12/6</span>, &nbsp; <span class=\"math\">−1 = -6/6</span>.<br>\n            Five rational numbers: <span class=\"math\"><strong>-11/6, -10/6, -9/6, -8/6, -7/6</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) Between −4/5 and −2/3:</strong><br>\n            LCM of 5 and 3 is 15. Make denominators equal to <span class=\"math\">15 × 3 = 45</span>:<br>\n            <span class=\"math\">-4/5 = -36/45</span>, &nbsp; <span class=\"math\">-2/3 = -30/45</span>.<br>\n            Five rational numbers: <span class=\"math\"><strong>-35/45, -34/45, -33/45, -32/45, -31/45</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) Between −1/2 and 2/3:</strong><br>\n            LCM of 2 and 3 is 6. Multiply by 2 ⇒ denominator 12:<br>\n            <span class=\"math\">-1/2 = -6/12</span>, &nbsp; <span class=\"math\">2/3 = 8/12</span>.<br>\n            Five rational numbers: <span class=\"math\"><strong>-5/12, -4/12, 0, 1/12, 5/12</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Finding suitable common denominator &amp; listing 5 rationals</span><span class=\"marking-marks\">1 Mark each (4 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Rewrite the following rational numbers in the simplest (standard) form:<br>(i) −8/6<br>(ii) 25/45<br>(iii) −44/72<br>(iv) −8/10</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Divide numerator and denominator by their HCF:</p>\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">-8/6</span>:</strong><br>\n            HCF of 8 and 6 is 2: <span class=\"math\">-(8 ÷ 2)/(6 ÷ 2) = <strong>-4/3</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">25/45</span>:</strong><br>\n            HCF of 25 and 45 is 5: <span class=\"math\">(25 ÷ 5)/(45 ÷ 5) = <strong>5/9</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">-44/72</span>:</strong><br>\n            HCF of 44 and 72 is 4: <span class=\"math\">-(44 ÷ 4)/(72 ÷ 4) = <strong>-11/18</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) <span class=\"math\">-8/10</span>:</strong><br>\n            HCF of 8 and 10 is 2: <span class=\"math\">-(8 ÷ 2)/(10 ÷ 2) = <strong>-4/5</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct reduction to simplest standard form</span><span class=\"marking-marks\">0.5 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Which is greater in each of the following?<br>(i) 2/3, 5/2<br>(ii) −5/6, −4/3<br>(iii) −3/4, 2/−3<br>(iv) −3 2/7, −3 4/5</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 2/3 and 5/2:</strong><br>\n            LCM = 6: <span class=\"math\">2/3 = 4/6</span>, <span class=\"math\">5/2 = 15/6</span>.<br>\n            Since <span class=\"math\">15 > 4 ⇒ <strong>5/2 > 2/3</strong></span>. (Also 5/2 &gt; 1 while 2/3 &lt; 1).\n          </div>\n          <div class=\"step\">\n            <strong>(ii) −5/6 and −4/3:</strong><br>\n            LCM = 6: <span class=\"math\">-5/6</span>, <span class=\"math\">-4/3 = -8/6</span>.<br>\n            On the number line, <span class=\"math\">−5 > −8</span>. Hence, <span class=\"math\"><strong>-5/6 > -4/3</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) −3/4 and 2/−3:</strong><br>\n            In standard form: <span class=\"math\">-3/4</span> and <span class=\"math\">-2/3</span>.<br>\n            LCM = 12: <span class=\"math\">-3/4 = -9/12</span>, <span class=\"math\">-2/3 = -8/12</span>.<br>\n            Since <span class=\"math\">−8 > −9 ⇒ <strong>2/(−3) > -3/4</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) −3 2/7 and −3 4/5:</strong><br>\n            <span class=\"math\">-3 2/7 = -23/7 = -115/35</span>.<br>\n            <span class=\"math\">-3 4/5 = -19/5 = -133/35</span>.<br>\n            Since <span class=\"math\">−115 > −133 ⇒ <strong>-3 2/7 > -3 4/5</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting to common denominator and comparing numerators</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 8.2 -->\n  <div class=\"ex-div\">Exercise 8.2 (Operations on Rational Numbers)</div>\n\n  <div class=\"q-card\" id=\"q8_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the sum:<br>(i) 5/4 + (−11/4)<br>(ii) 5/3 + 3/5<br>(iii) −9/10 + 22/15<br>(iv) −3/−11 + 5/9<br>(v) −8/19 + (−2/57)<br>(vi) −2⅓ + 4⅗</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">5/4 + (-11/4) = (5 − 11)/4 = (−6)/4 = <strong>-3/2</strong> = <strong>-1 1/2</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">5/3 + 3/5</span>:</strong> LCM = 15.<br>\n            <span class=\"math\">= (5 × 5 + 3 × 3)/15 = (25 + 9)/15 = <strong>34/15</strong> = <strong>2 4/15</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">-9/10 + 22/15</span>:</strong> LCM = 30.<br>\n            <span class=\"math\">= (−9 × 3 + 22 × 2)/30 = (−27 + 44)/30 = <strong>17/30</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) <span class=\"math\">(−3)/(−11) + 5/9 = 3/11 + 5/9</span>:</strong> LCM = 99.<br>\n            <span class=\"math\">= (3 × 9 + 5 × 11)/99 = (27 + 55)/99 = <strong>82/99</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(v) <span class=\"math\">-8/19 + (-2/57)</span>:</strong> LCM = 57.<br>\n            <span class=\"math\">= (−8 × 3 − 2)/57 = (−24 − 2)/57 = <strong>-26/57</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(vi) <span class=\"math\">-2 1/3 + 4 3/5 = -7/3 + 23/5</span>:</strong> LCM = 15.<br>\n            <span class=\"math\">= (−7 × 5 + 23 × 3)/15 = (−35 + 69)/15 = <strong>34/15</strong> = <strong>2 4/15</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct fraction addition with LCM steps</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the product:<br>(i) 9/2 × (−7/4)<br>(ii) 3/10 × (−9)<br>(iii) −6/5 × 9/11<br>(iv) 3/7 × (−2/5)<br>(v) 3/−5 × (−5/3)</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">9/2 × (-7/4) = (9 × (−7))/(2 × 4) = <strong>-63/8</strong> = <strong>-7 7/8</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">3/10 × (−9) = (3 × (−9))/10 = <strong>-27/10</strong> = <strong>-2 7/10</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">-6/5 × 9/11 = (−6 × 9)/(5 × 11) = <strong>-54/55</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iv) <span class=\"math\">3/7 × (-2/5) = (3 × (−2))/(7 × 5) = <strong>-6/35</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(v) <span class=\"math\">3/(−5) × (-5/3) = (−3)/5 × (−5)/3 = ((−3) × (−5))/(5 × 3) = 15/15 = <strong>1</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplying numerators and denominators with correct signs</span><span class=\"marking-marks\">0.5 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Find the value of:<br>(i) (−4) ÷ 2/3<br>(ii) −3/5 ÷ 2<br>(iii) −4/5 ÷ (−3)<br>(iv) −1/8 ÷ 3/4<br>(v) −2/13 ÷ 1/7<br>(vi) −7/12 ÷ (−2/13)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Multiply the first number by the reciprocal of the divisor:</p>\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">(−4) ÷ 2/3 = (−4) × 3/2 = −2 × 3 = <strong>−6</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">-3/5 ÷ 2 = -3/5 × 1/2 = <strong>-3/10</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">-4/5 ÷ (−3) = -4/5 × (-1/3) = <strong>4/15</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iv) <span class=\"math\">-1/8 ÷ 3/4 = -1/8 × 4/3 = <strong>-1/6</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(v) <span class=\"math\">-2/13 ÷ 1/7 = -2/13 × 7/1 = <strong>-14/13</strong> = <strong>-1 1/13</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(vi) <span class=\"math\">-7/12 ÷ (-2/13) = -7/12 × (-13/2) = <strong>91/24</strong> = <strong>3 19/24</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reciprocal inversion &amp; accurate evaluation</span><span class=\"marking-marks\">0.5 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Insertion of Rationals</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> Is it true that there are only 5 rational numbers between −1 and 0? Explain mathematically how many rational numbers exist between any two distinct rational numbers.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: No, it is not true.</strong></p>\n          <p>Between any two distinct rational numbers, there are <strong>infinitely many rational numbers</strong>.</p>\n          <p><em>Reasoning:</em> We can multiply the numerator and denominator by any arbitrarily large integer <span class=\"math\">k</span>. For example, choosing <span class=\"math\">k = 100</span> gives <span class=\"math\">-100/100</span> and <span class=\"math\">0/100</span>, yielding 99 rational numbers. Choosing <span class=\"math\">k = 10,000</span> yields 9,999 rational numbers. By choosing <span class=\"math\">k</span> arbitrarily large, we can insert as many rational numbers as we desire. This fundamental property is called the <strong>Density Property</strong> of rational numbers.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(7)\">← Chapter 7: Comparing Quantities</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\">Chapter 9: Perimeter &amp; Area →</button>\n  </div>\n</section>\n","9":"<section class=\"chapter-section\" id=\"ch9\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">9</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 9: Perimeter and Area</h2>\n      <p>NCERT Exercise 9.1 to 9.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Mensuration Formulas Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Square &amp; Rectangle:</strong>\n        <ul>\n          <li>Perimeter of square = 4 × side;   Area of square = side².</li>\n          <li>Perimeter of rectangle = 2(l + b);   Area of rectangle = l × b.</li>\n        </ul>\n      </li>\n      <li><strong>Area of Parallelogram:</strong>\n        Area = Base × Height = b × h\n      </li>\n      <li><strong>Area of Triangle:</strong>\n        Area = 1/2 × Base × Height = 1/2 b h\n        (Every triangle can be viewed as half of a parallelogram with the same base and height).\n      </li>\n      <li><strong>Circle:</strong>\n        <ul>\n          <li>Circumference = 2π r = π d (where π ≈ 22/7 or 3.14).</li>\n          <li>Area of circle = π r².</li>\n          <li>Area of circular ring / path = π (R² - r²) = π(R + r)(R - r).</li>\n        </ul>\n      </li>\n      <li><strong>Unit Conversions:</strong>\n        1 cm² = 100 mm²,   1 m² = 10,000 cm²,   1 hectare = 10,000 m².\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 9.1 -->\n  <div class=\"ex-div\">Exercise 9.1 (Parallelograms &amp; Triangles)</div>\n\n  <div class=\"q-card\" id=\"q9_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the area of each of the following parallelograms:<br>(a) base = 7 cm, height = 4 cm<br>(b) base = 5 cm, height = 3 cm<br>(c) base = 2.5 cm, height = 3.5 cm<br>(d) base = 5 cm, height = 4.8 cm<br>(e) base = 2 cm, height = 4.4 cm</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Formula: <span class=\"math\">Area of parallelogram = base × height</span>.</p>\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">Area = 7 cm × 4 cm = <strong>28 cm²</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(b) <span class=\"math\">Area = 5 cm × 3 cm = <strong>15 cm²</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(c) <span class=\"math\">Area = 2.5 cm × 3.5 cm = <strong>8.75 cm²</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(d) <span class=\"math\">Area = 5 cm × 4.8 cm = <strong>24 cm²</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(e) <span class=\"math\">Area = 2 cm × 4.4 cm = <strong>8.8 cm²</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula stated: Base × Height</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with proper units (cm²)</span><span class=\"marking-marks\">0.5 Mark each (2.5 Marks)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the area of each of the following triangles:<br>(a) base = 4 cm, height = 3 cm<br>(b) base = 5 cm, height = 3.2 cm<br>(c) base = 3 cm, height = 4 cm (right-angled)<br>(d) base = 3 cm, height = 2 cm (obtuse)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Formula: <span class=\"math\">Area of triangle = 1/2 × base × height</span>.</p>\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">Area = 1/2 × 4 × 3 = 2 × 3 = <strong>6 cm²</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(b) <span class=\"math\">Area = 1/2 × 5 × 3.2 = 5 × 1.6 = <strong>8 cm²</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(c) <span class=\"math\">Area = 1/2 × 3 × 4 = 3 × 2 = <strong>6 cm²</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(d) <span class=\"math\">Area = 1/2 × 3 × 2 = <strong>3 cm²</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula stated: ½ × Base × Height</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with unit (cm²)</span><span class=\"marking-marks\">0.5 Mark each (2 Marks)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">ΔABC is right angled at A. AD is perpendicular to BC. If AB = 5 cm, BC = 13 cm and AC = 12 cm, find the area of ΔABC. Also find the length of AD.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Calculate Area of ΔABC using legs AB and AC:</strong><br>\n            Since right angle is at A, legs <span class=\"math\">AB = 5 cm</span> and <span class=\"math\">AC = 12 cm</span> serve as base and height.<br>\n            <span class=\"math\">Area = 1/2 × AB × AC = 1/2 × 5 × 12 = 5 × 6 = <strong>30 cm²</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Find altitude AD using hypotenuse BC as base:</strong><br>\n            <span class=\"math\">Area = 1/2 × BC × AD</span><br>\n            <span class=\"math\">30 = 1/2 × 13 × AD ⇒ AD = (30 × 2)/13 = 60/13 = <strong>4 8/13 cm</strong> ≈ 4.62 cm</span>.\n          </div>\n          <p><strong>Conclusion:</strong> Area of ΔABC is <strong>30 cm²</strong> and length of <span class=\"math\">AD</span> is <strong>60/13 cm (4.62 cm)</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Area = ½ × 5 × 12 = 30 cm²</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Equating ½ × 13 × AD = 30 ⇒ AD = 60/13 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 9.2 -->\n  <div class=\"ex-div\">Exercise 9.2 (Circles: Circumference &amp; Area)</div>\n\n  <div class=\"q-card\" id=\"q9_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the circumference of the circles with the following radius (Take π = 22/7):<br>(a) 14 cm<br>(b) 28 mm<br>(c) 21 cm</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Formula: <span class=\"math\">C = 2π r</span>.</p>\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">C = 2 × 22/7 × 14 = 2 × 22 × 2 = <strong>88 cm</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(b) <span class=\"math\">C = 2 × 22/7 × 28 = 2 × 22 × 4 = <strong>176 mm</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(c) <span class=\"math\">C = 2 × 22/7 × 21 = 2 × 22 × 3 = <strong>132 cm</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula 2πr + each evaluation</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the area of the following circles, given that (Take π = 22/7):<br>(a) radius = 14 mm<br>(b) diameter = 49 m<br>(c) radius = 5 cm</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Formula: <span class=\"math\">Area = π r²</span>.</p>\n          <div class=\"step\">\n            <strong>(a) r = 14 mm:</strong><br>\n            <span class=\"math\">Area = 22/7 × 14 × 14 = 22 × 2 × 14 = <strong>616 mm²</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) d = 49 m ⇒ r = 49/2 m:</strong><br>\n            <span class=\"math\">Area = 22/7 × 49/2 × 49/2 = (11 × 7 × 49)/2 = 3773/2 = <strong>1886.5 m²</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) r = 5 cm:</strong><br>\n            <span class=\"math\">Area = 22/7 × 5 × 5 = 550/7 = <strong>78 4/7 cm²</strong> ≈ 78.57 cm²</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with formula and units</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">A gardener wants to fence a circular garden of diameter 21 m. Find the length of the rope he needs to purchase, if he makes 2 rounds of fence. Also find the cost of the rope, if it costs ₹4 per metre. (Take π = 22/7)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Calculate circumference of garden:</strong><br>\n            Diameter <span class=\"math\">d = 21 m ⇒ r = 21/2 m</span>.<br>\n            <span class=\"math\">C = 2π r = 2 × 22/7 × 21/2 = 22 × 3 = <strong>66 m</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Total length of rope for 2 rounds:</strong><br>\n            <span class=\"math\">Length of rope = 2 × C = 2 × 66 = <strong>132 m</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Calculate total cost:</strong><br>\n            Cost per metre = <span class=\"math\">₹4</span>.<br>\n            <span class=\"math\">Total Cost = 132 × ₹4 = <strong>₹528</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> He needs <strong>132 metres</strong> of rope and the total cost is <strong>₹528</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Circumference C = 66 m</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rope length for 2 rounds = 132 m</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total cost = 132 × 4 = ₹528</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">From a circular sheet of radius 4 cm, a circle of radius 3 cm is removed. Find the area of the remaining sheet. (Take π = 3.14)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Area of outer circular sheet (R = 4 cm):</strong><br>\n            <span class=\"math\">Area₁ = π R² = 3.14 × 4² = 3.14 × 16 = <strong>50.24 cm²</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Area of removed circle (r = 3 cm):</strong><br>\n            <span class=\"math\">Area₂ = π r² = 3.14 × 3² = 3.14 × 9 = <strong>28.26 cm²</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Area of remaining sheet:</strong><br>\n            <span class=\"math\">Area = Area₁ − Area₂ = 50.24 − 28.26 = <strong>21.98 cm²</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The area of the remaining sheet is <strong>21.98 cm²</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Outer area = 50.24 cm²</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inner area = 28.26 cm²</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Difference = 21.98 cm²</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Wire Rebent from Square to Rectangle</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> A wire is in the shape of a square of side 10 cm. If the wire is rebent into a rectangle of length 12 cm, find its breadth. Which figure encloses more area and by how much?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>1. Length of wire (Perimeter):</strong><br>\n          <span class=\"math\">Perimeter of square = 4 × side = 4 × 10 = <strong>40 cm</strong></span>.<br>\n          When rebent into a rectangle, perimeter is still 40 cm:<br>\n          <span class=\"math\">2(l + b) = 40 ⇒ 2(12 + b) = 40 ⇒ 12 + b = 20 ⇒ b = 20 − 12 = <strong>8 cm</strong></span>.</p>\n          <p><strong>2. Compare Areas:</strong><br>\n          <span class=\"math\">Area of square = side² = 10 × 10 = <strong>100 cm²</strong></span>.<br>\n          <span class=\"math\">Area of rectangle = l × b = 12 × 8 = <strong>96 cm²</strong></span>.<br>\n          Difference = <span class=\"math\">100 − 96 = <strong>4 cm²</strong></span>.<br>\n          <strong>Conclusion:</strong> The <strong>square</strong> encloses more area by <strong>4 cm²</strong>.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(8)\">← Chapter 8: Rational Numbers</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\">Chapter 10: Algebraic Expressions →</button>\n  </div>\n</section>\n","10":"<section class=\"chapter-section\" id=\"ch10\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">10</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 10: Algebraic Expressions</h2>\n      <p>NCERT Exercise 10.1 to 10.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Algebraic Rules Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Terms and Factors:</strong>\n        An algebraic expression is formed by terms. For example, in 4x² - 3xy, the terms are 4x² and -3xy. The factors of 4x² are 4, x, x and of -3xy are -3, x, y.\n      </li>\n      <li><strong>Coefficients:</strong> The numerical factor of a term is called its numerical coefficient (e.g. In -5xy, the coefficient is -5).</li>\n      <li><strong>Like and Unlike Terms:</strong>\n        <ul>\n          <li><em>Like terms:</em> Terms having the same algebraic factors with identical exponents (e.g. 7x and -12x, 4x^2y and -9x^2y).</li>\n          <li><em>Unlike terms:</em> Terms having different algebraic factors (e.g. 7x and 7y, 4x² and 4x).</li>\n        </ul>\n      </li>\n      <li><strong>Classification of Expressions:</strong>\n        <ul>\n          <li><em>Monomial:</em> Exactly one term (e.g. 7xy, -5).</li>\n          <li><em>Binomial:</em> Exactly two terms (e.g. a + b, 4x² - 3).</li>\n          <li><em>Trinomial:</em> Exactly three terms (e.g. a + b + c, x² + 5x + 6).</li>\n          <li><em>Polynomial:</em> An expression with one or more terms having non-negative integral exponents.</li>\n        </ul>\n      </li>\n      <li><strong>Addition and Subtraction:</strong> Only like terms can be combined (added or subtracted) by adding their numerical coefficients.</li>\n      <li><strong>Evaluating Expressions:</strong> Substitute the given numerical values of variables into the expression and apply BODMAS.</li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 10.1 -->\n  <div class=\"ex-div\">Exercise 10.1</div>\n\n  <div class=\"q-card\" id=\"q10_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Identify the terms and their factors in the following expressions:<br>(a) x − 3<br>(b) 1 + x + x²<br>(c) y − y³<br>(d) 5xy² + 7x²y<br>(e) −ab + 2b² − 3a²</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) x − 3:</strong><br>\n            • Term: <span class=\"math\">x</span> ⇒ Factors: <span class=\"math\">x</span><br>\n            • Term: <span class=\"math\">−3</span> ⇒ Factors: <span class=\"math\">−3</span> (or <span class=\"math\">−1, 3</span>)\n          </div>\n          <div class=\"step\">\n            <strong>(b) 1 + x + x²:</strong><br>\n            • Terms: <span class=\"math\">1, x, x²</span><br>\n            • Factors of <span class=\"math\">x²</span>: <span class=\"math\">x, x</span>\n          </div>\n          <div class=\"step\">\n            <strong>(c) y − y³:</strong><br>\n            • Terms: <span class=\"math\">y</span> and <span class=\"math\">−y³</span><br>\n            • Factors of <span class=\"math\">−y³</span>: <span class=\"math\">−1, y, y, y</span>\n          </div>\n          <div class=\"step\">\n            <strong>(d) 5xy² + 7x²y:</strong><br>\n            • Term: <span class=\"math\">5xy²</span> ⇒ Factors: <span class=\"math\">5, x, y, y</span><br>\n            • Term: <span class=\"math\">7x^2y</span> ⇒ Factors: <span class=\"math\">7, x, x, y</span>\n          </div>\n          <div class=\"step\">\n            <strong>(e) −ab + 2b² − 3a²:</strong><br>\n            • Term <span class=\"math\">−ab</span>: <span class=\"math\">−1, a, b</span><br>\n            • Term <span class=\"math\">2b²</span>: <span class=\"math\">2, b, b</span><br>\n            • Term <span class=\"math\">−3a²</span>: <span class=\"math\">−3, a, a</span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying terms and breaking into factors</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Classify into monomials, binomials and trinomials:<br>(i) 4y − 7z<br>(ii) y²<br>(iii) x + y − xy<br>(iv) 100<br>(v) ab − a − b<br>(vi) 5 − 3t<br>(vii) 4p²q − 4pq²<br>(viii) 7mn<br>(ix) z² − 3z + 8</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            • <strong>Monomials (1 term):</strong> (ii) <span class=\"math\">y²</span>, (iv) <span class=\"math\">100</span>, (viii) <span class=\"math\">7mn</span>.<br>\n            • <strong>Binomials (2 terms):</strong> (i) <span class=\"math\">4y − 7z</span>, (vi) <span class=\"math\">5 − 3t</span>, (vii) <span class=\"math\">4p^2q − 4pq²</span>.<br>\n            • <strong>Trinomials (3 terms):</strong> (iii) <span class=\"math\">x + y − xy</span>, (v) <span class=\"math\">ab − a − b</span>, (ix) <span class=\"math\">z² − 3z + 8</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct classification</span><span class=\"marking-marks\">0.33 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Simplify by combining like terms:<br>(i) 21b − 32 + 7b − 20b<br>(ii) −z² + 13z² − 5z + 7z³ − 15z<br>(iii) p − (p − q) − q − (q − p)<br>(iv) 3a − 2b − ab − (a − b + ab) + 3ab + b − a</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 21b − 32 + 7b − 20b:</strong><br>\n            Group terms with variable <span class=\"math\">b</span>:<br>\n            <span class=\"math\">= (21 + 7 − 20)b − 32 = (28 − 20)b − 32 = <strong>8b − 32</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) −z² + 13z² − 5z + 7z³ − 15z:</strong><br>\n            Arrange by descending powers of <span class=\"math\">z</span>:<br>\n            <span class=\"math\">= 7z³ + (−1 + 13)z² + (−5 − 15)z = <strong>7z³ + 12z² − 20z</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) p − (p − q) − q − (q − p):</strong><br>\n            Open parentheses with sign rules:<br>\n            <span class=\"math\">= p − p + q − q − q + p = (p − p + p) + (q − q − q) = <strong>p − q</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) 3a − 2b − ab − (a − b + ab) + 3ab + b − a:</strong><br>\n            Open brackets: <span class=\"math\">= 3a − 2b − ab − a + b − ab + 3ab + b − a</span>.<br>\n            Group like terms:<br>\n            • Terms in <span class=\"math\">a</span>: <span class=\"math\">(3 − 1 − 1)a = a</span><br>\n            • Terms in <span class=\"math\">b</span>: <span class=\"math\">(−2 + 1 + 1)b = 0b = 0</span><br>\n            • Terms in <span class=\"math\">ab</span>: <span class=\"math\">(−1 − 1 + 3)ab = ab</span><br>\n            <span class=\"math\">= <strong>a + ab</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Grouping like terms and simplifying</span><span class=\"marking-marks\">1 Mark each (4 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 10.2 -->\n  <div class=\"ex-div\">Exercise 10.2 (Evaluation of Expressions)</div>\n\n  <div class=\"q-card\" id=\"q10_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">If m = 2, find the value of:<br>(i) m − 2<br>(ii) 3m − 5<br>(iii) 9 − 5m<br>(iv) 3m² − 2m − 7<br>(v) 5m/2 − 4</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Substitute <span class=\"math\">m = 2</span>:</p>\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">m − 2 = 2 − 2 = <strong>0</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">3m − 5 = 3(2) − 5 = 6 − 5 = <strong>1</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">9 − 5m = 9 − 5(2) = 9 − 10 = <strong>−1</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iv) <span class=\"math\">3m² − 2m − 7 = 3(2)² − 2(2) − 7 = 3(4) − 4 − 7 = 12 − 11 = <strong>1</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(v) <span class=\"math\">5m/2 − 4 = 5(2)/2 − 4 = 5 − 4 = <strong>1</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct numerical evaluation</span><span class=\"marking-marks\">0.6 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">If a = 2, b = −2, find the value of:<br>(i) a² + b²<br>(ii) a² + ab + b²<br>(iii) a² − b²</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Given: <span class=\"math\">a = 2</span>, <span class=\"math\">b = −2</span>.</p>\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">a² + b² = (2)² + (−2)² = 4 + 4 = <strong>8</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">a² + ab + b² = (2)² + (2)(−2) + (−2)² = 4 − 4 + 4 = <strong>4</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">a² − b² = (2)² − (−2)² = 4 − 4 = <strong>0</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part evaluated with square of negative numbers</span><span class=\"marking-marks\">1 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Constant Determination</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> What should be the value of <span class=\"math\">a</span> if the value of <span class=\"math\">2x² + x − a</span> equals 5, when <span class=\"math\">x = 0</span>?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p>Given equation condition: <span class=\"math\">2x² + x − a = 5</span> when <span class=\"math\">x = 0</span>.</p>\n          <p>Substitute <span class=\"math\">x = 0</span> into the expression:<br>\n          <span class=\"math\">2(0)² + 0 − a = 5</span><br>\n          <span class=\"math\">0 + 0 − a = 5 ⇒ −a = 5 ⇒ <strong>a = −5</strong></span>.</p>\n          <p><strong>Conclusion:</strong> The value of <span class=\"math\">a</span> is <strong>−5</strong>.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(9)\">← Chapter 9: Perimeter &amp; Area</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\">Chapter 11: Exponents &amp; Powers →</button>\n  </div>\n</section>\n","11":"<section class=\"chapter-section\" id=\"ch11\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">11</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 11: Exponents and Powers</h2>\n      <p>NCERT Exercise 11.1 to 11.3 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Laws of Exponents Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Exponential Form:</strong> Repeated multiplication written concisely: a × a × a ... (n times) = aⁿ, where a is the <strong>base</strong> and n is the <strong>exponent</strong>.</li>\n      <li><strong>Laws of Exponents (for non-zero integers a, b and whole numbers m, n):</strong>\n        <ul>\n          <li><em>Multiplying powers with same base:</em> aᵐ × aⁿ = aᵐ⁺ⁿ.</li>\n          <li><em>Dividing powers with same base:</em> aᵐ ÷ aⁿ = aᵐ⁻ⁿ (m > n).</li>\n          <li><em>Power of a power:</em> (aᵐ)ⁿ = aᵐⁿ.</li>\n          <li><em>Multiplying powers with same exponents:</em> aᵐ × bᵐ = (a × b)ᵐ = (ab)ᵐ.</li>\n          <li><em>Dividing powers with same exponents:</em> aᵐ ÷ bᵐ = (a/b)ᵐ.</li>\n          <li><em>Zero Exponent:</em> a⁰ = 1.</li>\n          <li><em>Powers of -1:</em> (-1)eveⁿ = +1, (-1)odd = -1.</li>\n        </ul>\n      </li>\n      <li><strong>Standard Form (Scientific Notation):</strong>\n        Any number can be expressed as k × 10ⁿ, where 1 ≤ k < 10 and n is an integer. Used to write very large numbers compactly.\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 11.1 -->\n  <div class=\"ex-div\">Exercise 11.1</div>\n\n  <div class=\"q-card\" id=\"q11_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the value of:<br>(i) 2⁶<br>(ii) 9³<br>(iii) 11²<br>(iv) 5⁴</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">2⁶ = 2 × 2 × 2 × 2 × 2 × 2 = <strong>64</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">9³ = 9 × 9 × 9 = 81 × 9 = <strong>729</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">11² = 11 × 11 = <strong>121</strong></span></strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iv) <span class=\"math\">5⁴ = 5 × 5 × 5 × 5 = 25 × 25 = <strong>625</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation</span><span class=\"marking-marks\">0.5 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Express each of the following as product of powers of their prime factors:<br>(i) 648<br>(ii) 405<br>(iii) 540<br>(iv) 3,600</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 648:</strong><br>\n            <span class=\"math\">648 = 2 × 324 = 2 × 2 × 162 = 2 × 2 × 2 × 81 = 2³ × 3⁴ = <strong>2³ × 3⁴</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) 405:</strong><br>\n            <span class=\"math\">405 = 5 × 81 = 5 × 3⁴ = <strong>3⁴ × 5</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) 540:</strong><br>\n            <span class=\"math\">540 = 2 × 270 = 2 × 2 × 135 = 2² × 3 × 45 = 2² × 3³ × 5 = <strong>2² × 3³ × 5</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) 3,600:</strong><br>\n            <span class=\"math\">3600 = 36 × 100 = (2² × 3²) × (2² × 5²) = <strong>2⁴ × 3² × 5²</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Prime factorisation steps and final exponential notation</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Identify the greater number, wherever possible, in each of the following:<br>(i) 4³ or 3⁴<br>(ii) 5³ or 3⁵<br>(iii) 2⁸ or 8²<br>(iv) 100² or 2¹⁰⁰</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 4³ vs 3⁴:</strong><br>\n            <span class=\"math\">4³ = 4 × 4 × 4 = 64</span>.<br>\n            <span class=\"math\">3⁴ = 3 × 3 × 3 × 3 = 81</span>.<br>\n            Since <span class=\"math\">81 > 64 ⇒ <strong>3⁴ > 4³</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) 5³ vs 3⁵:</strong><br>\n            <span class=\"math\">5³ = 125</span>.<br>\n            <span class=\"math\">3⁵ = 243</span>.<br>\n            Since <span class=\"math\">243 > 125 ⇒ <strong>3⁵ > 5³</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) 2⁸ vs 8²:</strong><br>\n            <span class=\"math\">2⁸ = 256</span>.<br>\n            <span class=\"math\">8² = 64</span>.<br>\n            Since <span class=\"math\">256 > 64 ⇒ <strong>2⁸ > 8²</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) 100² vs 2¹⁰⁰:</strong><br>\n            <span class=\"math\">100² = 10,000</span>.<br>\n            Notice <span class=\"math\">2¹⁰ = 1024 > 1000 ⇒ 2¹⁰⁰ = (2¹⁰)¹⁰ > (10³)¹⁰ = 10³⁰</span>.<br>\n            Hence, <span class=\"math\"><strong>2¹⁰⁰ > 100²</strong></span> by an enormous margin.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation &amp; comparison</span><span class=\"marking-marks\">0.75 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 11.2 -->\n  <div class=\"ex-div\">Exercise 11.2 (Laws of Exponents)</div>\n\n  <div class=\"q-card\" id=\"q11_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Using laws of exponents, simplify and write the answer in exponential form:<br>(i) 3² × 3⁴ × 3⁸<br>(ii) 6¹⁵ ÷ 6¹⁰<br>(iii) a³ × a²<br>(iv) 7ˣ × 7²<br>(v) (5²)³ ÷ 5³<br>(vi) 2⁵ × 5⁵<br>(vii) (2²⁰ ÷ 2¹⁵) × 2³<br>(viii) 8ᵗ ÷ 8²</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">3² × 3⁴ × 3⁸ = 3² ⁺ ⁴ ⁺ ⁸ = <strong>3¹⁴</strong></span></strong> &nbsp;<em>[Law: aᵐ × aⁿ = aᵐ⁺ⁿ]</em><br>\n            <strong>(ii) <span class=\"math\">6¹⁵ ÷ 6¹⁰ = 6¹⁵ ⁻ ¹⁰ = <strong>6⁵</strong></span></strong> &nbsp;<em>[Law: aᵐ ÷ aⁿ = aᵐ⁻ⁿ]</em><br>\n            <strong>(iii) <span class=\"math\">a³ × a² = a³ ⁺ ² = <strong>a⁵</strong></span></strong><br>\n            <strong>(iv) <span class=\"math\">7ˣ × 7² = <strong>7ˣ⁺²</strong></span></strong><br>\n            <strong>(v) <span class=\"math\">(5²)³ ÷ 5³ = 5² × ³ ÷ 5³ = 5⁶ ÷ 5³ = 5⁶ ⁻ ³ = <strong>5³</strong></span></strong><br>\n            <strong>(vi) <span class=\"math\">2⁵ × 5⁵ = (2 × 5)⁵ = <strong>10⁵</strong></span></strong> &nbsp;<em>[Law: aᵐ × bᵐ = (ab)ᵐ]</em><br>\n            <strong>(vii) <span class=\"math\">(2²⁰ ÷ 2¹⁵) × 2³ = 2²⁰ ⁻ ¹⁵ × 2³ = 2⁵ × 2³ = 2⁵ ⁺ ³ = <strong>2⁸</strong></span></strong><br>\n            <strong>(viii) <span class=\"math\">8^t ÷ 8² = <strong>8t⁻²</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying exponent law formulas correctly</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">All 8 simplified exponential results</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Simplify and express each of the following in exponential form:<br>(i) (2³ × 3⁴ × 4) / (3 × 32)<br>(ii) [(5²)³ × 5⁴] ÷ 5⁷<br>(iii) 25⁴ ÷ 5³<br>(iv) (3 × 7² × 11⁸) / (21 × 11³)</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) <span class=\"math\">(2³ × 3⁴ × 4)/(3 × 32)</span>:</strong><br>\n            Express in prime factors: <span class=\"math\">4 = 2²</span>, <span class=\"math\">32 = 2⁵</span>.<br>\n            <span class=\"math\">= (2³ × 3⁴ × 2²)/(3¹ × 2⁵) = (2³⁺² × 3⁴)/(2⁵ × 3¹) = (2⁵ × 3⁴)/(2⁵ × 3¹) = 2⁵⁻⁵ × 3⁴⁻¹ = 2⁰ × 3³ = 1 × 3³ = <strong>3³</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) <span class=\"math\">[(5²)³ × 5⁴] ÷ 5⁷</span>:</strong><br>\n            <span class=\"math\">= [5² × ³ × 5⁴] ÷ 5⁷ = [5⁶ × 5⁴] ÷ 5⁷ = 5⁶⁺⁴ ÷ 5⁷ = 5¹⁰ ÷ 5⁷ = 5¹⁰⁻⁷ = <strong>5³</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) <span class=\"math\">25⁴ ÷ 5³</span>:</strong><br>\n            Write <span class=\"math\">25 = 5² ⇒ (5²)⁴ ÷ 5³ = 5⁸ ÷ 5³ = 5⁸⁻³ = <strong>5⁵</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) <span class=\"math\">(3 × 7² × 11⁸)/(21 × 11³)</span>:</strong><br>\n            Write <span class=\"math\">21 = 3 × 7</span>.<br>\n            <span class=\"math\">= (3¹ × 7² × 11⁸)/(3¹ × 7¹ × 11³) = 3¹⁻¹ × 7²⁻¹ × 11⁸⁻³ = 3⁰ × 7¹ × 11⁵ = 1 × 7 × 11⁵ = <strong>7 × 11⁵</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Prime base conversion &amp; exponent law steps</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 11.3 -->\n  <div class=\"ex-div\">Exercise 11.3 (Expanded Form &amp; Scientific Notation)</div>\n\n  <div class=\"q-card\" id=\"q11_3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Write the following numbers in expanded forms using powers of 10:<br>(i) 279404<br>(ii) 3006194<br>(iii) 2806196</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 279404:</strong><br>\n            <span class=\"math\">= 2 × 10⁵ + 7 × 10⁴ + 9 × 10³ + 4 × 10² + 0 × 10¹ + 4 × 10⁰</span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) 3006194:</strong><br>\n            <span class=\"math\">= 3 × 10⁶ + 0 × 10⁵ + 0 × 10⁴ + 6 × 10³ + 1 × 10² + 9 × 10¹ + 4 × 10⁰</span>.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) 2806196:</strong><br>\n            <span class=\"math\">= 2 × 10⁶ + 8 × 10⁵ + 0 × 10⁴ + 6 × 10³ + 1 × 10² + 9 × 10¹ + 6 × 10⁰</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct expanded power-of-10 representation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Express the following in standard scientific form (k × 10ⁿ):<br>(a) 5,00,00,000<br>(b) 70,00,000<br>(c) 3,18,65,00,000<br>(d) 39087.8<br>(e) Distance between Sun and Earth = 149,600,000,000 m<br>(f) Speed of light in vacuum = 300,000,000 m/s</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Scientific notation format: <span class=\"math\">k × 10ⁿ</span> where <span class=\"math\">1 ≤ k < 10</span>.</p>\n          <div class=\"step\">\n            <strong>(a) <span class=\"math\">5,00,00,000 = <strong>5.0 × 10⁷</strong></span></strong><br>\n            <strong>(b) <span class=\"math\">70,00,000 = <strong>7.0 × 10⁶</strong></span></strong><br>\n            <strong>(c) <span class=\"math\">3,18,65,00,000 = <strong>3.1865 × 10⁹</strong></span></strong><br>\n            <strong>(d) <span class=\"math\">39087.8 = <strong>3.90878 × 10⁴</strong></span></strong><br>\n            <strong>(e) <span class=\"math\">149,600,000,000 m = <strong>1.496 × 10¹¹ m</strong></span></strong><br>\n            <strong>(f) <span class=\"math\">300,000,000 m/s = <strong>3.0 × 10⁸ m/s</strong></span></strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct standard form representation</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Finding Unknown Exponent</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> Find the value of <span class=\"math\">x</span> in the equation: <span class=\"math\">(2/5)³ × (2/5)⁶ = (2/5)³ˣ</span>.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p>Using law <span class=\"math\">aᵐ × aⁿ = aᵐ⁺ⁿ</span> on LHS:<br>\n          <span class=\"math\">(2/5)³ ⁺ ⁶ = (2/5)³ˣ</span><br>\n          <span class=\"math\">(2/5)⁹ = (2/5)³ˣ</span>.</p>\n          <p>Equating exponents since bases are identical:<br>\n          <span class=\"math\">3x = 9 ⇒ x = 9/3 = <strong>3</strong></span>.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(10)\">← Chapter 10: Algebraic Expressions</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\">Chapter 12: Symmetry →</button>\n  </div>\n</section>\n","12":"<section class=\"chapter-section\" id=\"ch12\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">12</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 12: Symmetry</h2>\n      <p>NCERT Exercise 12.1 to 12.3 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; Symmetry Properties Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Line Symmetry:</strong> A figure has line symmetry if a line can be drawn dividing it into two identical halves that coincide exactly when folded along that line.</li>\n      <li><strong>Lines of Symmetry for Regular Polygons:</strong>\n        Each regular polygon of n sides has exactly n lines of symmetry:\n        <ul>\n          <li>Equilateral triangle: 3 lines</li>\n          <li>Square: 4 lines</li>\n          <li>Regular pentagon: 5 lines</li>\n          <li>Regular hexagon: 6 lines</li>\n          <li>Circle: Infinitely many lines (along any diameter)</li>\n        </ul>\n      </li>\n      <li><strong>Rotational Symmetry:</strong> When a figure rotated around a fixed point (centre of rotation) by an angle ≤ 360° looks exactly the same as in its original orientation.</li>\n      <li><strong>Order of Rotational Symmetry:</strong> The number of times a figure fits onto itself in one full 360° rotation:\n        Order = 360°/(Angle of rotation)\n      </li>\n      <li><strong>Dual Symmetry:</strong> Figures possessing both line symmetry and rotational symmetry of order > 1 (e.g. Equilateral triangle, square, rectangle, circle, and English letters H, I, O, X).</li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 12.1 -->\n  <div class=\"ex-div\">Exercise 12.1 (Line Symmetry)</div>\n\n  <div class=\"q-card\" id=\"q12_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">State the number of lines of symmetry for the following figures:<br>(a) An equilateral triangle<br>(b) An isosceles triangle<br>(c) A scalene triangle<br>(d) A square<br>(e) A rectangle<br>(f) A rhombus<br>(g) A parallelogram<br>(h) A quadrilateral<br>(i) A regular hexagon<br>(j) A circle</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Equilateral Triangle:</strong> <strong>3 lines of symmetry</strong> (each altitude/median).<br>\n            <strong>(b) Isosceles Triangle:</strong> <strong>1 line of symmetry</strong> (bisector of vertex angle).<br>\n            <strong>(c) Scalene Triangle:</strong> <strong>0 lines of symmetry</strong> (none of the sides or angles are equal).<br>\n            <strong>(d) Square:</strong> <strong>4 lines of symmetry</strong> (2 diagonals + 2 perpendicular bisectors of opposite sides).<br>\n            <strong>(e) Rectangle:</strong> <strong>2 lines of symmetry</strong> (perpendicular bisectors of opposite sides).<br>\n            <strong>(f) Rhombus:</strong> <strong>2 lines of symmetry</strong> (along the two diagonals).<br>\n            <strong>(g) Parallelogram:</strong> <strong>0 lines of symmetry</strong> (in general, cannot be folded to coincide).<br>\n            <strong>(h) Quadrilateral:</strong> <strong>0 lines of symmetry</strong> (in general).<br>\n            <strong>(i) Regular Hexagon:</strong> <strong>6 lines of symmetry</strong> (3 joining opposite vertices + 3 joining midpoints of opposite sides).<br>\n            <strong>(j) Circle:</strong> <strong>Infinitely many lines of symmetry</strong> (any straight line through the centre / diameter).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct geometric figure symmetry count</span><span class=\"marking-marks\">0.4 Mark each (4 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">What letters of the English alphabet have reflectional symmetry (i.e. symmetry related to mirror reflection) about:<br>(a) a vertical mirror<br>(b) a horizontal mirror<br>(c) both horizontal and vertical mirrors</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Vertical Mirror Symmetry (Left-Right reflection):</strong><br>\n            Letters: <strong>A, H, I, M, O, T, U, V, W, X, Y</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) Horizontal Mirror Symmetry (Top-Bottom reflection):</strong><br>\n            Letters: <strong>B, C, D, E, H, I, K, O, X</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) Both Horizontal and Vertical Mirrors:</strong><br>\n            Letters in the intersection of both sets: <strong>H, I, O, X</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): Vertical symmetry letters</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): Horizontal symmetry letters</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c): Both vertical &amp; horizontal (H, I, O, X)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 12.2 -->\n  <div class=\"ex-div\">Exercise 12.2 (Rotational Symmetry)</div>\n\n  <div class=\"q-card\" id=\"q12_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Give the order of the rotational symmetry and the angle of rotation for each of the following figures:<br>(a) Square<br>(b) Rectangle<br>(c) Rhombus<br>(d) Equilateral triangle<br>(e) Regular hexagon<br>(f) Circle</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Square:</strong><br>\n            • Centre of rotation: Intersection of diagonals.<br>\n            • Angle of rotation: <span class=\"math\">360°/4 = <strong>90°</strong></span>.<br>\n            • Order of rotational symmetry = <strong>4</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) Rectangle:</strong><br>\n            • Centre of rotation: Intersection of diagonals.<br>\n            • Angle of rotation: <span class=\"math\">360°/2 = <strong>180°</strong></span>.<br>\n            • Order of rotational symmetry = <strong>2</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) Rhombus:</strong><br>\n            • Centre of rotation: Intersection of diagonals.<br>\n            • Angle of rotation: <span class=\"math\">360°/2 = <strong>180°</strong></span>.<br>\n            • Order of rotational symmetry = <strong>2</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(d) Equilateral Triangle:</strong><br>\n            • Centre of rotation: Centroid (intersection of medians).<br>\n            • Angle of rotation: <span class=\"math\">360°/3 = <strong>120°</strong></span>.<br>\n            • Order of rotational symmetry = <strong>3</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(e) Regular Hexagon:</strong><br>\n            • Centre of rotation: Centre of hexagon.<br>\n            • Angle of rotation: <span class=\"math\">360°/6 = <strong>60°</strong></span>.<br>\n            • Order of rotational symmetry = <strong>6</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(f) Circle:</strong><br>\n            • Centre of rotation: Centre of circle.<br>\n            • Angle of rotation: <strong>Any angle θ</strong>.<br>\n            • Order of rotational symmetry = <strong>Infinitely many</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each figure: Order and angle of rotation</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Can we have a rotational symmetry of order more than 1 whose angle of rotation is:<br>(i) 45°?<br>(ii) 17°?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Rule:</strong> A figure can have rotational symmetry if and only if the angle of rotation divides <span class=\"math\">360°</span> completely without a remainder.</p>\n          <div class=\"step\">\n            <strong>(i) Angle of rotation = 45°:</strong><br>\n            <span class=\"math\">360°/45° = 8</span> (an exact integer).<br>\n            <strong>Yes</strong>, we can have a rotational symmetry of order 8 (e.g. a regular octagon).\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Angle of rotation = 17°:</strong><br>\n            <span class=\"math\">360°/17° = 21.176...</span> (not an integer).<br>\n            <strong>No</strong>, since 360° is not divisible by 17°, a rotational symmetry of order more than 1 is not possible.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Yes with division 360/45 = 8</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): No with divisibility justification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 12.3 -->\n  <div class=\"ex-div\">Exercise 12.3 (Dual Symmetry)</div>\n\n  <div class=\"q-card\" id=\"q12_3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Name any two figures that have both line symmetry and rotational symmetry.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. A Square:</strong><br>\n            • Has 4 lines of symmetry.<br>\n            • Has rotational symmetry of order 4 (angle of rotation = 90°).\n          </div>\n          <div class=\"step\">\n            <strong>2. An Equilateral Triangle:</strong><br>\n            • Has 3 lines of symmetry.<br>\n            • Has rotational symmetry of order 3 (angle of rotation = 120°).<br>\n            <em>(A Circle or Regular Hexagon are also valid examples).</em>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct geometric figure with its dual symmetry properties</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Alphabet Symmetry Analysis</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> Name any two letters of the English alphabet that possess: (i) Both line symmetry and rotational symmetry, (ii) Only rotational symmetry of order > 1 but no line symmetry.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Both line and rotational symmetry:</strong><br>\n          Letters <strong>H, I, O, X</strong>.<br>\n          • Letter H has 2 lines of symmetry (1 vertical, 1 horizontal) and rotational symmetry of order 2 (rotates by 180°).<br>\n          • Letter O has infinitely many lines of symmetry and infinite rotational symmetry.</p>\n          <p><strong>(ii) Only rotational symmetry (no line symmetry):</strong><br>\n          Letters <strong>S, Z, N</strong>.<br>\n          • Letter S rotates by 180° onto itself (order 2), but cannot be folded along any line to coincide.<br>\n          • Letter Z rotates by 180° (order 2), but has no line of symmetry.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(11)\">← Chapter 11: Exponents &amp; Powers</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\">Chapter 13: Visualising Solid Shapes →</button>\n  </div>\n</section>\n","13":"<section class=\"chapter-section\" id=\"ch13\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">13</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 13: Visualising Solid Shapes</h2>\n      <p>NCERT Exercise 13.1 to 13.3 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Concepts &amp; 3-D Solid Properties Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>3-Dimensional Shapes (Solids):</strong> Figures with length, breadth, and height/depth (e.g. Cube, Cuboid, Cylinder, Cone, Sphere, Prism, Pyramid).</li>\n      <li><strong>Polyhedrons:</strong> Solids formed entirely of polygonal planar regions called <strong>Faces</strong> (F). The line segments where faces meet are <strong>Edges</strong> (E). The points where edges meet are <strong>Vertices</strong> (V).</li>\n      <li><strong>Euler’s Formula:</strong> For any convex polyhedron:\n        F + V - E = 2\n      </li>\n      <li><strong>Net of a Solid:</strong> A 2-D outline skeleton on paper that can be folded along its edges to construct the 3-D solid shape.</li>\n      <li><strong>Visualising Cross-Sections:</strong>\n        <ul>\n          <li><em>Horizontal cut (parallel to base):</em> Slicing through the height.</li>\n          <li><em>Vertical cut (perpendicular to base):</em> Slicing through the cross-axis.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <!-- EXERCISE 13.1 -->\n  <div class=\"ex-div\">Exercise 13.1 (Nets of 3-D Solids)</div>\n\n  <div class=\"q-card\" id=\"q13_1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Identify the nets which can be used to make cubes (cut out copies of the nets and try it). How many faces does a cube have?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Properties of a Cube Net:</strong><br>\n            • A cube has exactly <strong>6 identical square faces</strong>, <strong>12 edges</strong>, and <strong>8 vertices</strong>.<br>\n            • In a valid cube net, no two folded squares overlap, and opposite faces never share a common edge in the net.<br>\n            • Standard valid nets include the \"T-shape\" (1-4-1 pattern), the cross-shape, and the step patterns (2-3-1 pattern).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating cube has 6 faces</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying valid non-overlapping foldable nets</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q13_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Name the solid that each net can make:<br>(a) A net with 2 identical circular bases and 1 rectangular surface<br>(b) A net with 1 circular base and 1 sector of a circle<br>(c) A net with 1 square base and 4 triangular faces<br>(d) A net with 2 triangular bases and 3 rectangular faces</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) 2 circular bases + 1 rectangular lateral face:</strong> <strong>Cylinder</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) 1 circular base + 1 sector:</strong> <strong>Cone</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(c) 1 square base + 4 triangular faces meeting at apex:</strong> <strong>Square Pyramid</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(d) 2 triangular bases + 3 rectangular faces:</strong> <strong>Triangular Prism</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correctly identified 3-D solid</span><span class=\"marking-marks\">0.75 Mark each (3 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 13.2 -->\n  <div class=\"ex-div\">Exercise 13.2 (Isometric Sketches &amp; Dimension Combining)</div>\n\n  <div class=\"q-card\" id=\"q13_2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Three cubes each with 2 cm edge are placed side by side to form a cuboid. What would be the dimensions (length, breadth, and height) of this cuboid?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Geometry Analysis:</strong><br>\n            Edge of each cube = <span class=\"math\">2 cm</span>.<br>\n            When 3 cubes are placed side by side in a row:<br>\n            • Length (<span class=\"math\">l</span>) = <span class=\"math\">2 + 2 + 2 = <strong>6 cm</strong></span>.<br>\n            • Breadth (<span class=\"math\">b</span>) remains unchanged = <span class=\"math\"><strong>2 cm</strong></span>.<br>\n            • Height (<span class=\"math\">h</span>) remains unchanged = <span class=\"math\"><strong>2 cm</strong></span>.\n          </div>\n          <p><strong>Conclusion:</strong> The dimensions of the resulting cuboid are <strong>6 cm × 2 cm × 2 cm</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Length = 2 + 2 + 2 = 6 cm</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Breadth = 2 cm, Height = 2 cm</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- EXERCISE 13.3 -->\n  <div class=\"ex-div\">Exercise 13.3 (Cross-Sections of Solids)</div>\n\n  <div class=\"q-card\" id=\"q13_3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What cross-section do you get when you give a: (i) vertical cut, (ii) horizontal cut to the following solids?<br>(a) A brick<br>(b) A round apple<br>(c) A die<br>(d) A circular pipe<br>(e) An ice cream cone</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) A brick (Cuboid):</strong><br>\n            (i) Vertical cut: <strong>Rectangle</strong><br>\n            (ii) Horizontal cut: <strong>Rectangle</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(b) A round apple (Sphere):</strong><br>\n            (i) Vertical cut: <strong>Circle</strong><br>\n            (ii) Horizontal cut: <strong>Circle</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(c) A die (Cube):</strong><br>\n            (i) Vertical cut: <strong>Square</strong><br>\n            (ii) Horizontal cut: <strong>Square</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(d) A circular pipe (Cylinder):</strong><br>\n            (i) Vertical cut (along axis): <strong>Rectangle</strong><br>\n            (ii) Horizontal cut (parallel to base): <strong>Circular ring</strong> (or Circle)\n          </div>\n          <div class=\"step\">\n            <strong>(e) An ice cream cone (Cone):</strong><br>\n            (i) Vertical cut (through apex): <strong>Isosceles Triangle</strong><br>\n            (ii) Horizontal cut (parallel to base): <strong>Circle</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each solid: Vertical and horizontal cut cross-section shape</span><span class=\"marking-marks\">0.8 Mark each (4 Marks total)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q13_3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Verify Euler’s formula (F + V − E = 2) for:<br>(a) A Cuboid<br>(b) A Triangular Prism<br>(c) A Square Pyramid</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Euler's formula: <span class=\"math\">F + V − E = 2</span>.</p>\n          <div class=\"step\">\n            <strong>(a) Cuboid:</strong><br>\n            • Faces (<span class=\"math\">F</span>) = 6<br>\n            • Vertices (<span class=\"math\">V</span>) = 8<br>\n            • Edges (<span class=\"math\">E</span>) = 12<br>\n            Verification: <span class=\"math\">F + V − E = 6 + 8 − 12 = 14 − 12 = <strong>2</strong></span>. <strong>Verified!</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(b) Triangular Prism:</strong><br>\n            • Faces (<span class=\"math\">F</span>) = 5 (2 triangular + 3 rectangular)<br>\n            • Vertices (<span class=\"math\">V</span>) = 6<br>\n            • Edges (<span class=\"math\">E</span>) = 9<br>\n            Verification: <span class=\"math\">F + V − E = 5 + 6 − 9 = 11 − 9 = <strong>2</strong></span>. <strong>Verified!</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(c) Square Pyramid:</strong><br>\n            • Faces (<span class=\"math\">F</span>) = 5 (1 square + 4 triangular)<br>\n            • Vertices (<span class=\"math\">V</span>) = 5 (1 apex + 4 base corners)<br>\n            • Edges (<span class=\"math\">E</span>) = 8 (4 base edges + 4 slant edges)<br>\n            Verification: <span class=\"math\">F + V − E = 5 + 5 − 8 = 10 − 8 = <strong>2</strong></span>. <strong>Verified!</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each solid: F, V, E count and verification of F + V − E = 2</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Euler's Formula Polyhedron Test</div>\n        <div class=\"cbq-question\"><strong>Problem:</strong> Can a polyhedron have 10 faces, 20 edges and 15 vertices? Justify your answer using Euler’s formula.</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p>Given parameters:<br>\n          Faces, <span class=\"math\">F = 10</span><br>\n          Edges, <span class=\"math\">E = 20</span><br>\n          Vertices, <span class=\"math\">V = 15</span>.</p>\n          <p>By Euler's Formula for any polyhedron:<br>\n          <span class=\"math\">F + V − E = 2</span>.</p>\n          <p>Substituting given values:<br>\n          <span class=\"math\">LHS = F + V − E = 10 + 15 − 20 = 25 − 20 = <strong>5</strong></span>.</p>\n          <p>Since <span class=\"math\">5 ≠ 2</span>, the given values violate Euler’s formula.</p>\n          <p><strong>Conclusion:</strong> <strong>No</strong>, a polyhedron cannot have 10 faces, 20 edges, and 15 vertices.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(12)\">← Chapter 12: Symmetry</button>\n    <button class=\"ch-nav-btn\" disabled style=\"opacity:.35;\">Next Chapter →</button>\n  </div>\n</section>\n"};
